@verbatim
<section class="hero" id="hero">

  <!-- Ambient Layers -->
  <!-- Spatial scene layers — soft, theme-aware -->
  <div class="hero__keylight"></div>
  <div class="hero__horizon"></div>
  <div class="hero__ground"></div>
  <div class="hero__ambient"></div>
  <div class="hero__noise"></div>
  <div class="hero__grid"></div>

  <!-- Deep-Space Cosmic Field — populated by JS on load -->
  <div class="hero__particles" id="cosmicField"></div>

  <!-- ── LEFT: TEXT CONTENT ── -->
  <div class="hero__content" id="main" tabindex="-1">

    <div class="hero__logo">
      <img src="assets/img/logo.svg" alt="Crypto Cipher® Audio Lab" class="hero__logo-img">
    </div>

    <h1 class="hero__title" data-reveal-hero data-reveal-delay="0">
      <span class="hero__title-top">From the Spirit of</span>
      <span class="hero__title-main">INDIA</span>
    </h1>

    <p class="hero__subtitle" data-reveal-hero data-reveal-delay="120">
      Authentic instruments, ancient traditions — crafted&nbsp;for the modern music composer.
    </p>

    <div class="hero__ctas" data-reveal-hero data-reveal-delay="240">
      <a href="#featured-libraries" class="cta-pill" data-magnetic aria-label="Virtual Instrument Libraries">
        <span class="cta-pill__label">Virtual Instrument Libraries</span>
        <span class="cta-pill__arrow" aria-hidden="true">→</span>
        <span class="cta-pill__meter" aria-hidden="true">
          <i></i><i></i><i></i><i></i>
        </span>
      </a>
      <a href="#recording" class="cta-inline">
        Recording services <span class="cta-inline__arrow" aria-hidden="true">→</span>
      </a>
    </div>
  </div>

  <!-- ── CTA BUTTONS — mobile reorder copy ── -->
  <div class="hero__ctas-mobile">
    <a href="#featured-libraries" class="cta-pill" aria-label="Virtual Instrument Libraries">
      <span class="cta-pill__label">Virtual Instrument Libraries</span>
      <span class="cta-pill__arrow" aria-hidden="true">→</span>
      <span class="cta-pill__meter" aria-hidden="true">
        <i></i><i></i><i></i><i></i>
      </span>
    </a>
    <a href="#recording" class="cta-inline">
      Recording services <span class="cta-inline__arrow" aria-hidden="true">→</span>
    </a>
  </div>

  <!-- ── RIGHT: INTERACTIVE INDIA HERITAGE MAP (inlined) ── -->
  <div class="hero__map-stage">
    <div class="hero__map-wrap">
      <div class="cc-map" data-cc-map="india-heritage">
<!-- ═══ RIGHT PANE (60%) — MAP ═══ -->
  <div class="map-stage" id="mapStage">
    <!-- ═══ HOVER TOOLTIP — click icon + state name ═══
         Click icon (cream/white) with lime glow + state name in uppercase.
         Hidden when popup is active. -->
    <div class="map-hover-label" id="mapHoverLabel" aria-hidden="true">
      <svg class="map-hover-label-icon" viewBox="0 0 32 32" width="20" height="20" xmlns="http://www.w3.org/2000/svg">
        <g class="hover-icon-rays" stroke="currentColor" stroke-linecap="round" fill="none">
          <line x1="16" y1="2" x2="16" y2="5.5" stroke-width="1.4"/>
          <line x1="24.7" y1="5.5" x2="22.3" y2="7.9" stroke-width="1.4"/>
          <line x1="28" y1="14" x2="24.5" y2="14" stroke-width="1.4"/>
          <line x1="7.3" y1="5.5" x2="9.7" y2="7.9" stroke-width="1.4"/>
          <line x1="4" y1="14" x2="7.5" y2="14" stroke-width="1.4"/>
        </g>
        <g class="hover-icon-hand" fill="currentColor">
          <path d="M14.1 9.5 v 8.5 c0 0.4 -0.5 0.6 -0.8 0.3 l -1.6 -1.7 c -0.7 -0.7 -1.9 -0.5 -2.3 0.4 c -0.3 0.7 -0.1 1.5 0.4 2.0 l 4.6 4.7 c 0.5 0.5 1.2 0.8 1.9 0.8 h 4.8 c 1.5 0 2.8 -1.1 3.0 -2.6 l 0.7 -5.0 c 0.2 -1.5 -1.0 -2.8 -2.5 -2.8 h -1.1 v -0.6 c 0 -0.9 -0.7 -1.6 -1.6 -1.6 c -0.4 0 -0.7 0.1 -1.0 0.3 c -0.2 -0.7 -0.8 -1.2 -1.5 -1.2 c -0.5 0 -0.9 0.2 -1.2 0.5 v -0.5 c 0 -1.1 -0.9 -2.0 -2.0 -2.0 c -1.1 0 -1.8 0.9 -1.8 2.0 z"/>
        </g>
      </svg>
      <span class="map-hover-label-name"></span>
    </div>
    
    <div class="map-tilt" id="mapTilt">

      <!-- Layered shadow stack for 3D depth -->
      <div class="map-shadow-far"></div>
      <div class="map-shadow-mid"></div>
      <div class="map-shadow-near"></div>

      <div class="map-svg-wrap">
        <!--
          PHASE 2 NOTE: Replace stylized regional shapes below with verified
          Survey of India 2024 GeoJSON paths. Each <path> already has the
          correct id and data-* attributes — only the `d` attribute changes.
          Boundary requirement: solid lines for J&K (incl. PoK), Ladakh
          (incl. Aksai Chin), full Arunachal Pradesh.
        -->
        <svg class="india-map" viewBox="0 0 1000 1000" xmlns="http://www.w3.org/2000/svg">

          <defs>
            <!-- ═══════════════════════════════════════════════════════════════
                 CINEMATIC DEPTH SYSTEM
                 - Single dark graphite base (no regional variation)
                 - Country reads as one carved object
                 - Hover lights up region in green from within dot field
                 ═══════════════════════════════════════════════════════════════ -->

            <!-- ═══ ENGRAVED HATCHING — REST STATE ═══
                 Copper-plate engraving aesthetic. Fine parallel lines etched into
                 the surface, with subtle highlight + shadow per line for carved feel.
                 Six directional variants assigned by region — same grammar, different
                 dialect, like a unified atlas style. -->

            <!-- 1. North/Himalayan — diagonal NE→SW (mountain ridge bias) -->
            <pattern id="hatch-north" x="0" y="0" width="14" height="14"
                     patternUnits="userSpaceOnUse" patternTransform="rotate(35)">
              <!-- Engraved line: dark groove + light highlight rim -->
              <line x1="0" y1="0" x2="0" y2="14"
                    stroke="rgba(255,255,255,0.05)" stroke-width="0.4"/>
              <line x1="0.6" y1="0" x2="0.6" y2="14"
                    stroke="rgba(187,214,122,0.18)" stroke-width="1.2"/>
              <line x1="1.2" y1="0" x2="1.2" y2="14"
                    stroke="rgba(0,0,0,0.55)" stroke-width="0.5"/>
            </pattern>

            <!-- 2. Northeast — vertical (bamboo/upright forest bias) -->
            <pattern id="hatch-ne" x="0" y="0" width="12" height="12"
                     patternUnits="userSpaceOnUse" patternTransform="rotate(0)">
              <line x1="0" y1="0" x2="0" y2="12"
                    stroke="rgba(255,255,255,0.06)" stroke-width="0.4"/>
              <line x1="0.5" y1="0" x2="0.5" y2="12"
                    stroke="rgba(187,214,122,0.2)" stroke-width="1.0"/>
              <line x1="1.1" y1="0" x2="1.1" y2="12"
                    stroke="rgba(0,0,0,0.5)" stroke-width="0.4"/>
            </pattern>

            <!-- 3. East/Bengal — flowing 60° (river-flow bias) -->
            <pattern id="hatch-east" x="0" y="0" width="14" height="14"
                     patternUnits="userSpaceOnUse" patternTransform="rotate(60)">
              <line x1="0" y1="0" x2="0" y2="14"
                    stroke="rgba(255,255,255,0.05)" stroke-width="0.4"/>
              <line x1="0.6" y1="0" x2="0.6" y2="14"
                    stroke="rgba(187,214,122,0.17)" stroke-width="1.1"/>
              <line x1="1.2" y1="0" x2="1.2" y2="14"
                    stroke="rgba(0,0,0,0.55)" stroke-width="0.5"/>
            </pattern>

            <!-- 4. Central — horizontal (plateau bias) -->
            <pattern id="hatch-central" x="0" y="0" width="12" height="12"
                     patternUnits="userSpaceOnUse" patternTransform="rotate(90)">
              <line x1="0" y1="0" x2="0" y2="12"
                    stroke="rgba(255,255,255,0.05)" stroke-width="0.4"/>
              <line x1="0.5" y1="0" x2="0.5" y2="12"
                    stroke="rgba(187,214,122,0.16)" stroke-width="1.0"/>
              <line x1="1.1" y1="0" x2="1.1" y2="12"
                    stroke="rgba(0,0,0,0.5)" stroke-width="0.4"/>
            </pattern>

            <!-- 5. West/Thar — diagonal NW→SE (desert dune bias) -->
            <pattern id="hatch-west" x="0" y="0" width="14" height="14"
                     patternUnits="userSpaceOnUse" patternTransform="rotate(-35)">
              <line x1="0" y1="0" x2="0" y2="14"
                    stroke="rgba(255,255,255,0.06)" stroke-width="0.4"/>
              <line x1="0.6" y1="0" x2="0.6" y2="14"
                    stroke="rgba(214,200,140,0.2)" stroke-width="1.2"/>
              <line x1="1.2" y1="0" x2="1.2" y2="14"
                    stroke="rgba(0,0,0,0.55)" stroke-width="0.5"/>
            </pattern>

            <!-- 6. South — concentric-suggesting 110° (Carnatic raga bias) -->
            <pattern id="hatch-south" x="0" y="0" width="13" height="13"
                     patternUnits="userSpaceOnUse" patternTransform="rotate(110)">
              <line x1="0" y1="0" x2="0" y2="13"
                    stroke="rgba(255,255,255,0.05)" stroke-width="0.4"/>
              <line x1="0.5" y1="0" x2="0.5" y2="13"
                    stroke="rgba(187,214,122,0.18)" stroke-width="1.1"/>
              <line x1="1.1" y1="0" x2="1.1" y2="13"
                    stroke="rgba(0,0,0,0.55)" stroke-width="0.5"/>
            </pattern>

            <!-- 7. Islands — fine horizontal (tide bias) -->
            <pattern id="hatch-islands" x="0" y="0" width="10" height="10"
                     patternUnits="userSpaceOnUse" patternTransform="rotate(90)">
              <line x1="0.4" y1="0" x2="0.4" y2="10"
                    stroke="rgba(187,214,122,0.18)" stroke-width="0.8"/>
              <line x1="0.9" y1="0" x2="0.9" y2="10"
                    stroke="rgba(0,0,0,0.5)" stroke-width="0.4"/>
            </pattern>

            <!-- ═══ HOVER VARIANTS — same geometry, illuminated green ═══ -->

            <pattern id="hatch-north-green" x="0" y="0" width="14" height="14"
                     patternUnits="userSpaceOnUse" patternTransform="rotate(35)">
              <line x1="0" y1="0" x2="0" y2="14" stroke="rgba(255,255,200,0.35)" stroke-width="0.4"/>
              <line x1="0.6" y1="0" x2="0.6" y2="14" stroke="#75C249" stroke-width="1.4"/>
              <line x1="1.2" y1="0" x2="1.2" y2="14" stroke="rgba(40,80,20,0.7)" stroke-width="0.5"/>
            </pattern>

            <pattern id="hatch-ne-green" x="0" y="0" width="12" height="12"
                     patternUnits="userSpaceOnUse" patternTransform="rotate(0)">
              <line x1="0" y1="0" x2="0" y2="12" stroke="rgba(255,255,200,0.4)" stroke-width="0.4"/>
              <line x1="0.5" y1="0" x2="0.5" y2="12" stroke="#75C249" stroke-width="1.2"/>
              <line x1="1.1" y1="0" x2="1.1" y2="12" stroke="rgba(40,80,20,0.7)" stroke-width="0.4"/>
            </pattern>

            <pattern id="hatch-east-green" x="0" y="0" width="14" height="14"
                     patternUnits="userSpaceOnUse" patternTransform="rotate(60)">
              <line x1="0" y1="0" x2="0" y2="14" stroke="rgba(255,255,200,0.35)" stroke-width="0.4"/>
              <line x1="0.6" y1="0" x2="0.6" y2="14" stroke="#75C249" stroke-width="1.3"/>
              <line x1="1.2" y1="0" x2="1.2" y2="14" stroke="rgba(40,80,20,0.7)" stroke-width="0.5"/>
            </pattern>

            <pattern id="hatch-central-green" x="0" y="0" width="12" height="12"
                     patternUnits="userSpaceOnUse" patternTransform="rotate(90)">
              <line x1="0" y1="0" x2="0" y2="12" stroke="rgba(255,255,200,0.35)" stroke-width="0.4"/>
              <line x1="0.5" y1="0" x2="0.5" y2="12" stroke="#75C249" stroke-width="1.2"/>
              <line x1="1.1" y1="0" x2="1.1" y2="12" stroke="rgba(40,80,20,0.7)" stroke-width="0.4"/>
            </pattern>

            <pattern id="hatch-west-green" x="0" y="0" width="14" height="14"
                     patternUnits="userSpaceOnUse" patternTransform="rotate(-35)">
              <line x1="0" y1="0" x2="0" y2="14" stroke="rgba(255,255,200,0.4)" stroke-width="0.4"/>
              <line x1="0.6" y1="0" x2="0.6" y2="14" stroke="#75C249" stroke-width="1.4"/>
              <line x1="1.2" y1="0" x2="1.2" y2="14" stroke="rgba(40,80,20,0.7)" stroke-width="0.5"/>
            </pattern>

            <pattern id="hatch-south-green" x="0" y="0" width="13" height="13"
                     patternUnits="userSpaceOnUse" patternTransform="rotate(110)">
              <line x1="0" y1="0" x2="0" y2="13" stroke="rgba(255,255,200,0.35)" stroke-width="0.4"/>
              <line x1="0.5" y1="0" x2="0.5" y2="13" stroke="#75C249" stroke-width="1.3"/>
              <line x1="1.1" y1="0" x2="1.1" y2="13" stroke="rgba(40,80,20,0.7)" stroke-width="0.5"/>
            </pattern>

            <pattern id="hatch-islands-green" x="0" y="0" width="10" height="10"
                     patternUnits="userSpaceOnUse" patternTransform="rotate(90)">
              <line x1="0.4" y1="0" x2="0.4" y2="10" stroke="#75C249" stroke-width="0.9"/>
              <line x1="0.9" y1="0" x2="0.9" y2="10" stroke="rgba(40,80,20,0.6)" stroke-width="0.4"/>
            </pattern>

            <!-- Legacy aliases — old IDs map to north hatch so existing markup works -->
            <pattern id="dot-field" xlink:href="#hatch-central" x="0" y="0" width="12" height="12" patternUnits="userSpaceOnUse"/>
            <pattern id="dot-field-green" xlink:href="#hatch-central-green" x="0" y="0" width="12" height="12" patternUnits="userSpaceOnUse"/>

            <!-- ═══ ATMOSPHERIC GRADIENT — north-cool / south-warm bias ═══
                 Stronger than NASA-subtle: visible warmth at rest while preserving
                 the bias. Lifts country off the dark void. -->
            <linearGradient id="atmospheric-bias" x1="0%" y1="0%" x2="0%" y2="100%">
              <stop offset="0%"   stop-color="#5a6a78" stop-opacity="0.7"/>
              <stop offset="35%"  stop-color="#6a7066" stop-opacity="0.5"/>
              <stop offset="65%"  stop-color="#7a7058" stop-opacity="0.5"/>
              <stop offset="100%" stop-color="#8a7a52" stop-opacity="0.7"/>
            </linearGradient>

            <!-- Country shell base — warmer tone, more luminous than before.
                 The shell itself catches some light at rest. -->
            <linearGradient id="grad-shell" x1="0%" y1="0%" x2="0%" y2="100%">
              <stop offset="0%"   stop-color="#2a2d33"/>
              <stop offset="50%"  stop-color="#1f2227"/>
              <stop offset="100%" stop-color="#16191d"/>
            </linearGradient>

            <!-- Animated radial glow under landmass for breathing effect -->
            <radialGradient id="ambient-pulse" cx="50%" cy="50%" r="70%">
              <stop offset="0%"  stop-color="rgba(117,194,73,0.18)"/>
              <stop offset="50%" stop-color="rgba(187,214,122,0.08)"/>
              <stop offset="100%" stop-color="rgba(0,0,0,0)"/>
            </radialGradient>

            <!-- ═══ STATE BASE — TRANSPARENT AT REST ═══
                 States are invisible at rest. Country reads as ONE landform.
                 State boundaries only appear via hover. -->
            <linearGradient id="grad-graphite" x1="0%" y1="0%" x2="0%" y2="100%">
              <stop offset="0%" stop-color="#000" stop-opacity="0"/>
              <stop offset="100%" stop-color="#000" stop-opacity="0"/>
            </linearGradient>

            <!-- All region IDs alias to transparent — no regional palette -->
            <linearGradient id="grad-north-1"   xlink:href="#grad-graphite"/>
            <linearGradient id="grad-north-2"   xlink:href="#grad-graphite"/>
            <linearGradient id="grad-north-3"   xlink:href="#grad-graphite"/>
            <linearGradient id="grad-ne-1"      xlink:href="#grad-graphite"/>
            <linearGradient id="grad-ne-2"      xlink:href="#grad-graphite"/>
            <linearGradient id="grad-ne-3"      xlink:href="#grad-graphite"/>
            <linearGradient id="grad-east-1"    xlink:href="#grad-graphite"/>
            <linearGradient id="grad-east-2"    xlink:href="#grad-graphite"/>
            <linearGradient id="grad-east-3"    xlink:href="#grad-graphite"/>
            <linearGradient id="grad-central-1" xlink:href="#grad-graphite"/>
            <linearGradient id="grad-central-2" xlink:href="#grad-graphite"/>
            <linearGradient id="grad-west-1"    xlink:href="#grad-graphite"/>
            <linearGradient id="grad-west-2"    xlink:href="#grad-graphite"/>
            <linearGradient id="grad-west-3"    xlink:href="#grad-graphite"/>
            <linearGradient id="grad-south-1"   xlink:href="#grad-graphite"/>
            <linearGradient id="grad-south-2"   xlink:href="#grad-graphite"/>
            <linearGradient id="grad-south-3"   xlink:href="#grad-graphite"/>
            <linearGradient id="grad-islands-1" xlink:href="#grad-graphite"/>
            <linearGradient id="grad-islands-2" xlink:href="#grad-graphite"/>

            <!-- ═══ CARVED SHELL FILTER — depth only, no green spill ═══
                 Removed wide+mid green flood (caused boxy halo at Sikkim/Mizoram). -->
            <filter id="carved-edge" x="-15%" y="-15%" width="130%" height="130%">
              <!-- Cast shadow -->
              <feGaussianBlur in="SourceAlpha" stdDeviation="6" result="castBlur"/>
              <feOffset in="castBlur" dx="0" dy="8" result="castOffset"/>
              <feFlood flood-color="#000" flood-opacity="0.65"/>
              <feComposite in2="castOffset" operator="in" result="castShadow"/>

              <!-- Inner recess shadow -->
              <feGaussianBlur in="SourceAlpha" stdDeviation="2" result="innerBlur"/>
              <feOffset in="innerBlur" dx="0" dy="2" result="innerOffset"/>
              <feComposite in="innerOffset" in2="SourceAlpha" operator="out" result="innerCutout"/>
              <feFlood flood-color="#000" flood-opacity="0.5"/>
              <feComposite in2="innerCutout" operator="in" result="innerShadow"/>

              <feMerge>
                <feMergeNode in="castShadow"/>
                <feMergeNode in="SourceGraphic"/>
                <feMergeNode in="innerShadow"/>
              </feMerge>
            </filter>

            <!-- ═══ HOVER BLOOM — 3-LAYER CINEMATIC LIGHT ═══
                 Inner: dots glow lime-green
                 Mid:   soft caustic feathered halo at 20px
                 Outer: distant atmospheric warmth radius -->
            <filter id="state-hover-glow" x="-60%" y="-60%" width="220%" height="220%">
              <!-- Outer atmospheric halo — wide, soft -->
              <feGaussianBlur stdDeviation="14" result="outerBlur"/>
              <feFlood flood-color="#BBD67A" flood-opacity="0.45"/>
              <feComposite in2="outerBlur" operator="in" result="outerGlow"/>
              
              <!-- Mid caustic bloom -->
              <feGaussianBlur in="SourceGraphic" stdDeviation="6" result="midBlur"/>
              <feFlood flood-color="#75C249" flood-opacity="0.75"/>
              <feComposite in2="midBlur" operator="in" result="midGlow"/>
              
              <feMerge>
                <feMergeNode in="outerGlow"/>
                <feMergeNode in="midGlow"/>
                <feMergeNode in="SourceGraphic"/>
              </feMerge>
            </filter>

            <!-- Legacy alias for any old reference -->
            <filter id="state-glow" x="-60%" y="-60%" width="220%" height="220%">
              <feGaussianBlur stdDeviation="6" result="blur"/>
              <feFlood flood-color="#BBD67A" flood-opacity="0.85"/>
              <feComposite in2="blur" operator="in"/>
              <feMerge><feMergeNode/><feMergeNode in="SourceGraphic"/></feMerge>
            </filter>

            <!-- ═══ COUNTRY MASK ═══
                 Used to clip atmospheric overlay to landmass shape only.
                 White = visible, black = clipped. -->
            <mask id="country-mask">
