          <!-- ═══ ATMOSPHERIC GRADIENT ═══
               North-cool / south-warm bias painted across landmass.
               Masked to country shape only. mix-blend overlay tints dots subtly. -->
          <rect class="atmospheric-layer"
                x="0" y="0" width="1000" height="1000"
                fill="url(#atmospheric-bias)"
                mask="url(#country-mask)"/>

          <!-- ═══ AMBIENT PULSE ═══
               Slow breathing radial warmth — country feels alive at rest -->
          <ellipse class="ambient-pulse-layer"
                   cx="500" cy="500" rx="400" ry="450"
                   fill="url(#ambient-pulse)"
                   mask="url(#country-mask)"/>

          <!-- ═══ STATIC ATMOSPHERIC HIGHLIGHT ═══
               Replaces rotating sweep. Soft top-light wash from upper-right
               that gives the landmass cinematic raked-light feel without motion. -->
          <g class="ambient-highlight" mask="url(#country-mask)">
            <defs>
              <radialGradient id="ambient-grad" cx="65%" cy="20%" r="80%">
                <stop offset="0%"   stop-color="rgba(255,240,210,0.18)"/>
                <stop offset="35%"  stop-color="rgba(255,230,180,0.08)"/>
                <stop offset="100%" stop-color="rgba(0,0,0,0)"/>
              </radialGradient>
            </defs>
            <rect x="0" y="0" width="1000" height="1000" fill="url(#ambient-grad)"/>
          </g>

          <!-- (Light-flow pulses removed per user request — map stays static) -->

          <!-- States layer — each state's hover region with dot-field overlay -->
          <!-- ═══ DIAMOND TILE MOSAIC — rasterization-based attribution ═══
               Each tile colored by which state CONTAINS its center.
               Geometry sourced via SVG rendering — perfectly matches browser. -->
          <g class="tile-mosaic"></g>
          <g class="states-layer">

