          <!-- Lakshadweep — geographically grounded representation.
               Real archipelago spans 8°N–12°30'N (370+ km north-south, only 32 km² total land).
               At world-map scale, real geometry is sub-pixel — we draw recognizable
               elongated atoll shapes in 3 cluster groups matching real layout:
                 • Amindivi Group (top)     — ~11°30'N to 12°N
                 • Laccadive Group (middle) — ~10°N to 11°30'N
                 • Minicoy (far south)      — ~8°N, isolated
               All islands are elongated north–south (real-world orientation). -->
          <g class="state-group island-group" id="state-lakshadweep" data-name="Lakshadweep" data-type="UT" data-region="Islands">
            
            <!-- ░░░ AMINDIVI GROUP — northernmost cluster ░░░ -->
            <!-- Chetlat / Bitra (smaller, northernmost) -->
            <ellipse class="state-frag" cx="225" cy="812" rx="2.5" ry="6" fill="url(#grad-islands-1)"/>
            <ellipse class="state-frag" cx="240" cy="820" rx="2" ry="5" fill="url(#grad-islands-1)"/>
            <!-- Kiltan -->
            <ellipse class="state-frag" cx="232" cy="832" rx="3" ry="7" fill="url(#grad-islands-1)"/>
            <!-- Kadmat (longest in group) -->
            <ellipse class="state-frag" cx="218" cy="848" rx="3" ry="9" fill="url(#grad-islands-1)"/>
            <!-- Amini -->
            <ellipse class="state-frag" cx="245" cy="852" rx="3" ry="6" fill="url(#grad-islands-1)"/>
            
            <!-- ░░░ LACCADIVE GROUP — middle cluster ░░░ -->
            <!-- Agatti (long, isolated to west) -->
