<!-- ═══════════════════════════════════════════════════════════════
     COSMIC FIELD — runs immediately on parse, before GSAP CDN.
     Generates stars/dust/shooting stars so the background is alive
     even before external scripts finish loading.
     ═══════════════════════════════════════════════════════════════ -->
<script>
(function () {
  'use strict';

  /* ═══════════════════════════════════════
     COSMIC ENVIRONMENT GENERATOR
     - Stars: 3 brightness tiers, randomized size/position/color/twinkle
     - Blinking dots: irregular cadence via 5 keyframe variants
     - Cosmic dust: random direction/curve/duration
     - Shooting stars: randomized timing/angle/origin/length per firing
     ═══════════════════════════════════════ */
  const rand = (min, max) => Math.random() * (max - min) + min;
  const randInt = (min, max) => Math.floor(rand(min, max + 1));
  const pick = (arr) => arr[randInt(0, arr.length - 1)];
  const chance = (p) => Math.random() < p;

  const cosmicField = document.getElementById('cosmicField');
  const isMobile = window.innerWidth < 1024;

  // Tunable: drop counts on mobile for fps
  const counts = {
    stars:    isMobile ? 50  : 90,
    bright:   isMobile ? 5   : 10,
    dust:     isMobile ? 6   : 12,
    shooters: isMobile ? 1   : 2
  };

  // Color palettes — astronomically plausible star colors
  const starColors = [
    { c: 'rgba(255,255,255,1)',   weight: 5 },  // white (most common)
    { c: 'rgba(220,235,255,1)',   weight: 3 },  // blue-white
    { c: 'rgba(255,240,220,1)',   weight: 3 },  // warm cream
    { c: 'rgba(255,220,200,1)',   weight: 2 },  // peach
    { c: 'rgba(200,220,255,1)',   weight: 2 },  // cool blue
    { c: 'rgba(255,200,150,1)',   weight: 1 },  // amber
    { c: 'rgba(220,200,255,1)',   weight: 1 }   // soft violet
  ];

  const dustColors = [
    'rgba(117,194,73,0.9)',
    'rgba(187,214,122,0.9)',
    'rgba(255,255,255,0.9)',
    'rgba(200,220,255,0.9)',
    'rgba(255,240,220,0.85)',
    'rgba(220,200,255,0.85)',
    'rgba(200,235,255,0.85)',
    'rgba(255,220,200,0.85)'
  ];

  // Weighted color picker
  function pickStarColor() {
    const total = starColors.reduce((s, x) => s + x.weight, 0);
    let r = rand(0, total);
    for (const sc of starColors) {
      if (r < sc.weight) return sc.c;
      r -= sc.weight;
    }
    return starColors[0].c;
  }

  // Reduce alpha for dim background stars
  function dimColor(rgba, alpha) {
    return rgba.replace(/rgba\(([^,]+),([^,]+),([^,]+),[^)]+\)/, `rgba($1,$2,$3,${alpha})`);
  }

  /* ── 1. Static starfield (background, dim, slow twinkle) ── */
  for (let i = 0; i < counts.stars; i++) {
    const star = document.createElement('div');
    star.className = 'cosmic-star';
    const size = rand(0.6, 1.6);
    const color = pickStarColor();
    const baseAlpha = rand(0.25, 0.7);
    star.style.left = rand(0, 100).toFixed(2) + '%';
    star.style.top = rand(0, 100).toFixed(2) + '%';
    star.style.width = size.toFixed(2) + 'px';
    star.style.height = size.toFixed(2) + 'px';
    star.style.background = dimColor(color, baseAlpha.toFixed(2));
    star.style.setProperty('--twinkle-min', (baseAlpha * 0.4).toFixed(2));
    star.style.setProperty('--twinkle-max', baseAlpha.toFixed(2));
    star.style.setProperty('--twinkle-min-scale', rand(0.7, 0.95).toFixed(2));
    star.style.setProperty('--twinkle-dur', rand(4, 12).toFixed(1) + 's');
    star.style.setProperty('--twinkle-delay', (-rand(0, 12)).toFixed(2) + 's');
    star.classList.add('cosmic-ready');
    cosmicField.appendChild(star);
  }

  /* ── 2. Bright stars with glow halo ── */
  for (let i = 0; i < counts.bright; i++) {
    const star = document.createElement('div');
    star.className = 'cosmic-star cosmic-star--bright';
    const size = rand(1.8, 3.2);
    const color = pickStarColor();
    const glowR = rand(3, 8);
    const baseAlpha = rand(0.7, 1);
    star.style.left = rand(2, 98).toFixed(2) + '%';
    star.style.top = rand(2, 98).toFixed(2) + '%';
    star.style.width = size.toFixed(2) + 'px';
    star.style.height = size.toFixed(2) + 'px';
    star.style.background = color;
    star.style.setProperty('--twinkle-min', (baseAlpha * 0.55).toFixed(2));
    star.style.setProperty('--twinkle-max', baseAlpha.toFixed(2));
    star.style.setProperty('--twinkle-min-scale', rand(0.75, 0.92).toFixed(2));
    star.style.setProperty('--twinkle-dur', rand(3, 7).toFixed(1) + 's');
    star.style.setProperty('--twinkle-delay', (-rand(0, 8)).toFixed(2) + 's');
    star.style.setProperty('--glow-c', dimColor(color, '0.5'));
    star.style.setProperty('--glow-r', glowR.toFixed(1) + 'px');
    star.classList.add('cosmic-ready');
    cosmicField.appendChild(star);
  }

  /* ── 3. Cosmic dust — drifting particles, random direction & curve ── */
  for (let i = 0; i < counts.dust; i++) {
    const dust = document.createElement('div');
    dust.className = 'cosmic-dust';
    const size = rand(1.2, 3.5);
    const color = pick(dustColors);
    const dirY = chance(0.7) ? -1 : 1;       // mostly upward, some downward
    const curveX = (chance(0.5) ? 1 : -1) * rand(15, 60);
    const duration = rand(18, 40);
    const delay = -rand(0, duration);        // already mid-flight on load
    const opacity = rand(0.35, 0.75);

    dust.style.left = rand(0, 100).toFixed(2) + '%';
    // Start position depends on direction
    dust.style.top = dirY === -1 ? '110%' : '-10%';
    dust.style.width = size.toFixed(2) + 'px';
    dust.style.height = size.toFixed(2) + 'px';
    dust.style.background = color;
    dust.style.boxShadow = `0 0 ${rand(3, 7).toFixed(0)}px ${color}`;
    dust.style.setProperty('--dir-y', dirY);
    dust.style.setProperty('--curve-x', curveX.toFixed(0) + 'px');
    dust.style.setProperty('--dust-dur', duration.toFixed(1) + 's');
    dust.style.setProperty('--dust-delay', delay.toFixed(1) + 's');
    dust.style.setProperty('--dust-opacity', opacity.toFixed(2));
    dust.style.animationDuration = duration.toFixed(1) + 's';
    dust.style.animationDelay = delay.toFixed(1) + 's';
    dust.classList.add('cosmic-ready');
    cosmicField.appendChild(dust);
  }

  /* ── 4. Shooting stars — small · left-to-right · sparse ── */
  function fireShootingStar(star) {
    // Single direction · left → right · low shallow angle
    const angle    = rand(8, 18);
    const top      = rand(8, 65);
    const length   = rand(50, 100);
    const opacity  = rand(0.35, 0.6);
    const duration = rand(7, 12).toFixed(2);
    const nextGap  = rand(12000, 28000);

    const tail = pick([
      'rgba(255,255,255,0.8)',
      'rgba(255,255,255,0.8)',
      'rgba(255,240,220,0.7)',
      'rgba(220,235,255,0.7)'
    ]);

    star.style.animation = 'none';
    star.style.top    = top.toFixed(1) + '%';
    star.style.left   = '-12%';
    star.style.width  = length.toFixed(0) + 'px';
    star.style.height = '1px';
    star.style.setProperty('--shoot-angle', angle.toFixed(1) + 'deg');
    star.style.setProperty('--shoot-end-x', rand(120, 135).toFixed(0) + 'vw');
    star.style.setProperty('--shoot-end-y', rand(15, 50).toFixed(0) + 'vh');
    star.style.setProperty('--streak-tail', tail);
    star.style.setProperty('--shoot-opacity', opacity.toFixed(2));
    void star.offsetWidth;
    star.style.animation = `shoot ${duration}s cubic-bezier(0.25, 0.46, 0.45, 0.94) 1`;
    star.classList.add('cosmic-ready');

    const totalMs = parseFloat(duration) * 1000 + nextGap;
    setTimeout(() => fireShootingStar(star), totalMs);
  }

  for (let i = 0; i < counts.shooters; i++) {
    const star = document.createElement('div');
    star.className = 'shooting-star';
    cosmicField.appendChild(star);
    setTimeout(() => fireShootingStar(star), 2500 + i * 6000 + rand(0, 8000));
  }

})();
</script>

<!-- GSAP 3 + ScrollTrigger — defer so they don't block initial render -->
<script defer src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/gsap.min.js"></script>
<script defer src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/ScrollTrigger.min.js"></script>

<!-- ═══════════════════════════════════════════════════════════════
     GSAP ENTRANCE ANIMATIONS — runs after CDN loads
     Cosmic field is already painted by the prior script.
     ═══════════════════════════════════════════════════════════════ -->
<script defer>
(function () {
  'use strict';

  function runEntrance() {

  /* ═══════════════════════════════════════
     ENTRANCE TIMELINE (GSAP)
     Add .js-ready to <body> only if GSAP loaded successfully.
     This activates the CSS rules that hide elements pre-animation.
     If GSAP fails to load (CDN blocked, offline), elements remain visible.
     ═══════════════════════════════════════ */
  if (typeof gsap === 'undefined') {
    // GSAP failed to load — leave content visible, skip animation.
    // Remove the synchronous 'js' flag so the critical html.js pre-animation
    // hide (opacity:0) stops applying and the hero CTAs/subtitle remain visible.
    document.documentElement.classList.remove('js');
    return;
  }
  document.body.classList.add('js-ready');

  const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (prefersReduced) {
    gsap.set([
      '.hero__logo', '.hero__title', '.hero__title-top', '.hero__title-main',
      '.hero__subtitle', '.hero__ctas', '.hero__ctas-mobile',
      '.hero__map-stage', '.hero__stats'
    ], { opacity: 1, y: 0, x: 0, scale: 1 });
    document.body.classList.remove('js-ready');
    return;
  }

  gsap.registerPlugin(ScrollTrigger);

  const ease = 'power3.out';
  const easeCinematic = 'power4.out';
  const isDesktop = window.innerWidth > 1024;

  const master = gsap.timeline({ defaults: { ease } });

  /* Logo */
  master.fromTo('.hero__logo',
    { opacity: 0, y: -30 },
    { opacity: 1, y: 0, duration: 1.2 },
    0.15
  );

  /* Title */
  master.fromTo('.hero__title',
    { opacity: 0 },
    { opacity: 1, duration: 0.1 },
    0.4
  );

  master.fromTo('.hero__title-top',
    { opacity: 0, y: 45, clipPath: 'inset(100% 0 0 0)' },
    { opacity: 1, y: 0, clipPath: 'inset(0% 0 0 0)', duration: 1.1, ease: easeCinematic },
    0.5
  );

  master.fromTo('.hero__title-main',
    { opacity: 0, y: 60, clipPath: 'inset(100% 0 0 0)' },
    { opacity: 1, y: 0, clipPath: 'inset(0% 0 0 0)', duration: 1.3, ease: easeCinematic },
    0.75
  );

  /* Underline (CSS var pseudo proxy) */
  master.to('.hero__title-main', {
    '--underline-width': '55%',
    '--underline-opacity': '0.5',
    duration: 1.4,
    ease: 'power2.inOut',
    onStart: function () {
      const el = document.querySelector('.hero__title-main');
      if (el) {
        el.style.setProperty('--underline-width', '0%');
        el.style.setProperty('--underline-opacity', '0');
        let sheet = document.getElementById('gsap-pseudo-styles');
        if (!sheet) {
          sheet = document.createElement('style');
          sheet.id = 'gsap-pseudo-styles';
          document.head.appendChild(sheet);
        }
        sheet.textContent = `
          .hero__title-main::after {
            width: var(--underline-width, 0%) !important;
            opacity: var(--underline-opacity, 0) !important;
          }
        `;
      }
    }
  }, 1.6);

  /* Subtitle */
  master.fromTo('.hero__subtitle',
    { opacity: 0, y: 30 },
    { opacity: 1, y: 0, duration: 0.9 },
    1.1
  );

  /* CTAs — desktop stagger / mobile fade. Guard targets: at some widths
     .hero__ctas is display:none, and GSAP fromTo on a missing target warns
     and can nudge layout — skip when the element isn't present. */
  if (isDesktop && document.querySelector('.hero__ctas')) {
    master.fromTo('.hero__ctas',
      { opacity: 0 },
      { opacity: 1, duration: 0.1 },
      1.4
    );
    if (document.querySelector('.hero__ctas .hero__cta')) {
      master.fromTo('.hero__ctas .hero__cta',
        { opacity: 0, x: -40, y: 15 },
        {
          opacity: 1, x: 0, y: 0,
          duration: 0.8,
          stagger: 0.12,
          ease: easeCinematic
        },
        1.45
      );
    }
  } else if (document.querySelector('.hero__ctas-mobile')) {
    master.fromTo('.hero__ctas-mobile',
      { opacity: 0, y: 25 },
      { opacity: 1, y: 0, duration: 0.8 },
      1.4
    );
  }

  /* Map fade-in — no horizontal transform on mobile to avoid layout interference */
  const isCurrentlyMobile = window.innerWidth <= 1024;
  if (isCurrentlyMobile) {
    /* MOBILE: opacity-only fade, no scale/transform that could leave residue */
    gsap.set('.hero__map-stage', { opacity: 1, x: 0, scale: 1, clearProps: 'transform,x,scale' });
    master.fromTo('.hero__map-stage',
      { opacity: 0 },
      { opacity: 1, duration: 1.5, ease: easeCinematic },
      0.3
    );
  } else {
    master.fromTo('.hero__map-stage',
      { opacity: 0, x: 80, scale: 0.95 },
      {
        opacity: 1, x: 0, scale: 1, duration: 2, ease: easeCinematic
      },
      0.3
    );
  }

  /* Stats bar — slide up from bottom */
  master.fromTo('.hero__stats',
    { opacity: 0, y: 20 },
    { opacity: 1, y: 0, duration: 1, ease: easeCinematic },
    isDesktop ? 2.2 : 1.8
  );

  /* Scroll indicator (desktop) */
  if (isDesktop && document.querySelector('.hero__scroll')) {
    master.fromTo('.hero__scroll',
      { opacity: 0 },
      { opacity: 1, duration: 0.8 },
      2.6
    );
  }

  /* ═══════════════════════════════════════
     STAT NUMBER COUNTERS
     Counts up on entrance after stats fade in.
     2010 stays static (year); others animate.
     ═══════════════════════════════════════ */
  function animateCounter(el, target, suffix, duration) {
    const obj = { val: 0 };
    gsap.to(obj, {
      val: target,
      duration: duration || 2,
      ease: 'power2.out',
      onUpdate: function () {
        const v = Math.floor(obj.val);
        el.textContent = v.toLocaleString() + suffix;
      }
    });
  }

  master.call(function () {
    const statNums = document.querySelectorAll('.hero__stat-number');
    if (!statNums.length) return;
    // Stat 1: 2010 — static (year)
    // Stat 2: 30+
    if (statNums[1]) animateCounter(statNums[1], 30, '+', 1.6);
    // Stat 3: 20,000+
    if (statNums[2]) animateCounter(statNums[2], 20000, '+', 2.2);
    // Stat 4: 14
    if (statNums[3]) animateCounter(statNums[3], 14, '', 1.4);
    // Stat 5: 1 (mission)
    if (statNums[4]) animateCounter(statNums[4], 1, '', 1.0);
  }, null, isDesktop ? 2.4 : 2.0);

  } // end runEntrance

  // Defer ensures DOM ready; if GSAP not yet attached, wait for window.load
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', runEntrance);
  } else {
    runEntrance();
  }

})();
</script>


