  'state-puducherry':          { tradition: 'French-Tamil colonial fusion, Carnatic foundations, coastal devotional music.', instruments: 'Mridangam, Nadaswaram, Violin', library: '/libraries/puducherry', collab: '/artists?state=puducherry' },
  'state-kerala':              { tradition: 'Sopanam temple tradition, Mappila Muslim folk, Kathakali classical theatre music.', instruments: 'Chenda, Idakka, Maddalam, Edakka', library: '/libraries/kerala', collab: '/artists?state=kerala' },
  'state-lakshadweep':         { tradition: 'Lava dance ceremonial music, Kolkali stick-dance traditions of the Arabian Sea atolls.', instruments: 'Dholak, Daff, Tabla', library: '/libraries/lakshadweep', collab: '/artists?state=lakshadweep' },
  'state-andaman-nicobar':     { tradition: 'Nicobarese tribal traditions, Onge and Jarawa indigenous heritage, ocean-rooted rhythms.', instruments: 'Bamboo flutes, Coconut shell percussion', library: '/libraries/andaman-nicobar', collab: '/artists?state=andaman-nicobar' }
};

// ═══════════════════════════════════════════════════════════════
// 3D PARALLAX TILT — desktop only
// ═══════════════════════════════════════════════════════════════
const stage = document.getElementById('mapStage');
const tilt = document.getElementById('mapTilt');
const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const isMobile = window.matchMedia('(max-width: 768px)').matches;

if (!reduceMotion && !isMobile) {
  stage.addEventListener('pointermove', (e) => {
    if (e.pointerType === 'touch') return;  // tilt only for mouse/pen
    const rect = stage.getBoundingClientRect();
    const x = (e.clientX - rect.left) / rect.width - 0.5;
    const y = (e.clientY - rect.top) / rect.height - 0.5;
    const rotY = x * 4;     // ±4° max — gentle for full-viewport
    const rotX = -y * 3;    // ±3° max
    tilt.style.transform = `rotateY(${rotY}deg) rotateX(${rotX}deg)`;
  });
  stage.addEventListener('pointerleave', () => {
    tilt.style.transform = 'rotateY(0deg) rotateX(0deg)';
  });
}

// ═══════════════════════════════════════════════════════════════
// (Pulse origin shifting removed — no pulses on map)
// ═══════════════════════════════════════════════════════════════

// ═══════════════════════════════════════════════════════════════
// HOVER + CLICK INTERACTION
// ───────────────────────────────────────────────────────────────
// Architecture:
//   1. Popup persists while hovering EITHER state OR popup itself
//   2. 250ms grace delay before hide — bridges cursor travel
//   3. Popup position locks on entry (does NOT track cursor)
//      — so user can move mouse INTO popup without it sliding
//   4. Inside popup: full pointer-events, scroll, click CTA
// ═══════════════════════════════════════════════════════════════
const popup = document.getElementById('statePopup');
const popupBody = popup.querySelector('.popup-body');
const popupFooter = popup.querySelector('.popup-footer');
const popupRegion = document.getElementById('popupRegion');
const popupTitle = document.getElementById('popupTitle');
const popupType = document.getElementById('popupType');
const popupTradition = document.getElementById('popupTradition');
const popupInstruments = document.getElementById('popupInstrumentList');
const popupCta = document.getElementById('popupCta');
const popupCollabCta = document.getElementById('popupCollabCta');

// ═══════════════════════════════════════════════════════════════
// CLICK-ONLY INTERACTION LAYER — v3
// 
// Hover is for affordance ONLY (cursor change + glow via CSS).
// Click is the only thing that opens or closes the popup.
// 
// State Machine (just two states):
//   IDLE    → no popup
//   PINNED  → popup open
// 
// Transitions:
//   IDLE   → click state    → PINNED
//   PINNED → click ×        → IDLE
//   PINNED → press Esc      → IDLE
//   PINNED → click outside  → IDLE
//   PINNED → click same state → IDLE (toggle)
//   PINNED → click another state → blocked (state-frags pointer-events: none)
// 
// To switch states, user must dismiss the current popup first.
// ═══════════════════════════════════════════════════════════════

class PopupController {
  constructor({ popup, popupRegion, popupTitle, popupType, popupTradition,
                popupInstruments, popupCta, popupCollabCta, popupBody,
                stateData }) {
    this.popup = popup;
    this.popupRegion = popupRegion;
    this.popupTitle = popupTitle;
    this.popupType = popupType;
    this.popupTradition = popupTradition;
    this.popupInstruments = popupInstruments;
    this.popupCta = popupCta;
    this.popupCollabCta = popupCollabCta;
    this.popupBody = popupBody;
    this.stateData = stateData;
    this.stage = document.querySelector('.map-stage');
    
    this.mode = 'IDLE';
    this.activeTarget = null;
  }
  
  // User clicks a state — definitive intent
  onClickState(target) {
    // Block during CTA suppression window (catches click drift)
    if (window._ctaClickGuardUntil && Date.now() < window._ctaClickGuardUntil) {
      return;
    }
    
    if (this.mode === 'PINNED' && this.activeTarget === target) {
      // Click on currently-pinned state → unpin
      this._teardown();
      return;
    }
    
    // If the map has been scrolled out of view (e.g. user is down at the
    // Featured Library section), the popup would open anchored to the
    // off-screen map. Scroll the hero back into view FIRST, wait for the
    // scroll to settle, THEN render — so the popup is always visible.
    // Desktop only: on mobile the popup is a centered floating card that
    // does not depend on map position, so no pre-scroll is needed.
    var isMobileViewport = window.matchMedia('(max-width: 1024px)').matches;
    if (!isMobileViewport) {
      /* MOTION v2: render instantly; the popup is viewport-fixed.
         Open on the OPPOSITE half from the clicked state. */
      var tr = target.getBoundingClientRect();
      var onRight = (tr.left + tr.right) / 2 > window.innerWidth / 2;
      this.popup.classList.toggle('cc-pop-left', onRight);
      this._render(target);
      return;
    }
    
    this._render(target);
  }
  
  // True when the map stage is comfortably within the viewport (not just a
  // sliver). 0.4 = at least 40% of the stage height showing.
  _isStageInView() {
    if (!this.stage) return true;            // no stage → don't block render
    var r = this.stage.getBoundingClientRect();
    var vh = window.innerHeight || document.documentElement.clientHeight;
    var visible = Math.min(r.bottom, vh) - Math.max(r.top, 0);
    return r.top < vh && r.bottom > 0 && visible > r.height * 0.4;
  }
  

  
  // Explicit dismiss (×, Esc, click outside)
  onDismiss() {
    this._teardown();
  }
  
  isOpen() {
    return this.mode === 'PINNED';
  }
  
  // ─── Private ───
  
  _render(target) {
    const id = target.id;
    const data = this.stateData[id];
    if (!data) return;
    
    if (this.activeTarget && this.activeTarget !== target) {
      this.activeTarget.classList.remove('active');
      // Also clear any lit hit-zone rings from the previously active UT.
      document.querySelectorAll('.ut-hitzone.active').forEach(function (z) { z.classList.remove('active'); });
    }
    this.activeTarget = target;
    target.classList.add('active');
    this.stage?.setAttribute('data-active-state', id);
    // Light EVERY hit-zone that targets this group (a UT may have multiple
    // markers — Daman + Diu are one UT and must glow together). Done here in
    // _render because on desktop the active target is set after a deferred
    // scroll, so the click handler can't reliably know it yet.
    document.querySelectorAll('.ut-hitzone').forEach(function (z) {
      if (z.dataset.target === id) z.classList.add('active');
      else z.classList.remove('active');
    });
    this.popupRegion.textContent = target.dataset.region;
    this.popupTitle.textContent = target.dataset.name;
    this.popupType.textContent = target.dataset.type === 'UT' ? 'Union Territory' : 'State';
    this.popupTradition.textContent = data.tradition;
    this.popupInstruments.textContent = data.instruments;
    this.popupCta.href = data.library;
    this.popupCollabCta.href = data.collab;
    this.popupBody.scrollTop = 0;
    
    this._positionPopup(target);
    this.popup.classList.add('state-active');
    this.popup.classList.add('pinned');
    this.mode = 'PINNED';
    /* MOTION v2: no scroll lock of any kind. The popup is viewport-fixed,
       so scrolling can never hide it; the page always belongs to the user. */
  }
  
  _teardown() {
    this.popup.classList.remove('state-active');
    this.popup.classList.remove('pinned');
    if (this.activeTarget) {
      this.activeTarget.classList.remove('active');
      this.activeTarget = null;
    }
    // Clear any lit hit-zone rings (a UT may have multiple, e.g. Daman + Diu).
    document.querySelectorAll('.ut-hitzone.active').forEach(function (z) { z.classList.remove('active'); });
    this.stage?.removeAttribute('data-active-state');
    this.mode = 'IDLE';
  }
  
  _positionPopup(target) {
    if (!this.stage) return;
    
    // Mobile: let CSS handle positioning (centered floating card at bottom).
    // Don't touch inline styles — they would override mobile media-query CSS.
    // Breakpoint MUST match the mobile popup CSS (@media max-width: 1024px).
    /* MOTION v2: the popup is viewport-fixed on every breakpoint (CSS owns
       placement), so it can never be hidden by scroll — which is the goal
       the old center-scroll + page-lock machinery existed to serve.
       The smart-placement code below is intentionally unreachable. */
    this.popup.style.removeProperty('left');
    this.popup.style.removeProperty('right');
    this.popup.style.removeProperty('top');
    this.popup.style.removeProperty('bottom');
    return;
    
    // Desktop / tablet: smart placement based on state position
    const stageRect = this.stage.getBoundingClientRect();
    const stateRect = target.getBoundingClientRect();
    const cx = (stateRect.left + stateRect.right) / 2 - stageRect.left;
    const cy = (stateRect.top + stateRect.bottom) / 2 - stageRect.top;
    const nx = cx / stageRect.width;
    const ny = cy / stageRect.height;
    
    const popupRight = nx < 0.55;
    const popupBottom = ny < 0.35;
    
    this.popup.style.removeProperty('left');
    this.popup.style.removeProperty('right');
    this.popup.style.removeProperty('top');
    this.popup.style.removeProperty('bottom');
    
    const sideMargin = '3.5rem';   /* breathing room from left/right edge */
    const topMargin = '6rem';      /* clear floating nav (~76px) */
    const bottomMargin = '6rem';   /* clear stats bar (~64px) */
    if (popupRight) { this.popup.style.right = sideMargin; this.popup.style.left = 'auto'; }
    else            { this.popup.style.left = sideMargin;  this.popup.style.right = 'auto'; }
    if (popupBottom) { this.popup.style.bottom = bottomMargin; this.popup.style.top = 'auto'; }
    else             { this.popup.style.top = topMargin;       this.popup.style.bottom = 'auto'; }
  }
}

// ═══════════════════════════════════════════════════════════════
// INITIALIZATION
// ═══════════════════════════════════════════════════════════════

const controller = new PopupController({
  popup, popupRegion, popupTitle, popupType, popupTradition,
  popupInstruments, popupCta, popupCollabCta, popupBody,
  stateData: STATE_DATA,
});

// ═══════════════════════════════════════════════════════════════
// HOVER TOOLTIP — cartographic state name beside cursor.
// Position tracks cursor. Shows after 80ms settle to avoid twitchy feel.
// Hides instantly when cursor leaves a state.
// ═══════════════════════════════════════════════════════════════
// HOVER TOOLTIP — click icon + state name beside cursor.
// Position tracks cursor. Shows after 80ms settle. Clamped to stage bounds.
// ═══════════════════════════════════════════════════════════════
const hoverLabel = document.getElementById('mapHoverLabel');
const hoverLabelName = hoverLabel?.querySelector('.map-hover-label-name');
let _hoverShowTimer = null;
let _hoverActiveStateId = null;

function showHoverLabel(stateId, stateName, clientX, clientY) {
  if (!hoverLabel || !hoverLabelName) return;
  if (controller.isOpen()) return;  // popup active — no tooltip
  
  const mapStage = document.getElementById('mapStage');
  if (!mapStage) return;
  
  // Update name BEFORE measuring so width is accurate
  if (_hoverActiveStateId !== stateId) {
    hoverLabelName.textContent = stateName;
  }
  
  // Convert viewport coords → map-stage-local coords
  const stageRect = mapStage.getBoundingClientRect();
  const localX = clientX - stageRect.left;
  const localY = clientY - stageRect.top;
  
  // Measure tooltip — chip width depends on state name length
  const labelW = hoverLabel.offsetWidth || 160;
  const labelH = hoverLabel.offsetHeight || 32;
  const cursorOffset = 14;
  const edgeMargin = 12;
  
  // Default: tooltip to right + below cursor
  let tipX = localX + cursorOffset;
  let tipY = localY + cursorOffset;
  
  // Flip near right edge
  if (tipX + labelW + edgeMargin > stageRect.width) {
    tipX = localX - cursorOffset - labelW;
  }
  // Flip near bottom edge
  if (tipY + labelH + edgeMargin > stageRect.height) {
    tipY = localY - cursorOffset - labelH;
  }
  tipX = Math.max(edgeMargin, tipX);
  tipY = Math.max(edgeMargin, tipY);
  
  hoverLabel.style.left = tipX + 'px';
  hoverLabel.style.top = tipY + 'px';
  
  // Already showing for this state? Just update position
  if (_hoverActiveStateId === stateId && hoverLabel.classList.contains('visible')) return;
  
  // New state hover — settle for 80ms then reveal
  _hoverActiveStateId = stateId;
  if (_hoverShowTimer) clearTimeout(_hoverShowTimer);
  if (!hoverLabel.classList.contains('visible')) {
    _hoverShowTimer = setTimeout(() => {
      if (_hoverActiveStateId === stateId && !controller.isOpen()) {
        hoverLabel.classList.add('visible');
      }
    }, 80);
  }
}

function hideHoverLabel() {
  if (!hoverLabel) return;
  if (_hoverShowTimer) {
    clearTimeout(_hoverShowTimer);
    _hoverShowTimer = null;
  }
  _hoverActiveStateId = null;
  hoverLabel.classList.remove('visible');
}

// ─── State group click bindings (no hover handlers, but track cursor for label) ───
document.querySelectorAll('.state-group').forEach(group => {
  const hitZones = group.querySelectorAll('.state-frag');
  const click = (e) => {
    e.stopPropagation();
    controller.onClickState(group);
  };
  
  // Cursor tracking for hover tooltip (no popup state changes — pure UI cue)
  const stateId = group.id;
  const stateName = group.dataset.name || '';
  const handlePointerMove = (e) => {
    if (controller.isOpen()) return;
    showHoverLabel(stateId, stateName, e.clientX, e.clientY);
  };
  const handlePointerLeave = () => hideHoverLabel();
  
  hitZones.forEach(hz => {
    hz.addEventListener('click', click);
    if (!isMobile) {
      hz.addEventListener('pointermove', handlePointerMove);
      hz.addEventListener('pointerleave', handlePointerLeave);
    }
  });
});

// ─── UT hit zone click bindings ───
document.querySelectorAll('.ut-hitzone').forEach(zone => {
  const targetId = zone.dataset.target;
  const targetGroup = document.getElementById(targetId);
  if (!targetGroup) return;
  const click = (e) => {
    e.stopPropagation();
    controller.onClickState(targetGroup);
    // Ring lighting is handled in controller._render / _teardown, which know
    // the true active target (set after a deferred scroll on desktop) and
    // light ALL zones for a multi-marker UT (e.g. Daman + Diu) together.
  };
  zone.addEventListener('click', click);
  
  if (!isMobile) {
    const stateId = targetGroup.id;
    const stateName = targetGroup.dataset.name || '';
    // Glow toggled on enter/leave (fires once each) so it holds steady while
    // the cursor is inside — NOT on pointermove, which on a tiny target
    // stutters (leave/enter retrigger) and restarts the glow animation.
    zone.addEventListener('pointerenter', () => {
      if (controller.isOpen()) return;
      if (zone.classList.contains('ut-hitzone--invisible')) targetGroup.classList.add('hover-glow');
      // Glow EVERY zone sharing this target, so a multi-marker UT (Daman + Diu)
      // lights both dots when the cursor enters either one.
      document.querySelectorAll('.ut-hitzone[data-target="' + targetId + '"]').forEach(function (z) {
        z.classList.add('hover-glow');
      });
    });
    zone.addEventListener('pointermove', (e) => {
      if (controller.isOpen()) return;
      showHoverLabel(stateId, stateName, e.clientX, e.clientY);
    });
    zone.addEventListener('pointerleave', () => {
      hideHoverLabel();
      targetGroup.classList.remove('hover-glow');
      document.querySelectorAll('.ut-hitzone[data-target="' + targetId + '"]').forEach(function (z) {
        z.classList.remove('hover-glow');
      });
    });
  }
});

// ─── Popup click trap (bubble phase) ───
// Stops clicks on popup surface from bubbling to document.
// Child handlers (× button, CTAs) fire FIRST due to bubble order.
popup.addEventListener('click', (e) => {
  e.stopPropagation();
  window._ctaClickGuardUntil = Date.now() + 300;
});
popup.addEventListener('pointerdown', (e) => {
  e.stopPropagation();
  window._ctaClickGuardUntil = Date.now() + 300;
});

window.__ccMapController = controller; /* mobile state-browser hook */

  /* No page lock while pinned → if the user scrolls the map stage fully
     out of view, close the popup instead of letting it strand off-screen. */
  if (controller.stage && 'IntersectionObserver' in window) {
    new IntersectionObserver(function (entries) {
      if (!entries[0].isIntersecting && controller.isOpen()) controller.onDismiss();
    }, { threshold: 0.02 }).observe(controller.stage);
  }

  // ─── Dismiss handlers ───
// Click outside popup AND outside any state → dismiss
document.addEventListener('click', (e) => {
  if (!controller.isOpen()) return;
  if (popup.contains(e.target)) return;
  if (e.target.closest('.state-group')) return;
  if (e.target.closest('.ut-hitzone')) return;
  controller.onDismiss();
});

// Esc → dismiss
document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape' && controller.isOpen()) controller.onDismiss();
});

/* MOTION v2: the "shake = close me to scroll" cue is retired - scrolling
   with the popup open is now ALLOWED (the popup is viewport-fixed), so the
   cue would fire on every legitimate scroll. */

// × close button
const popupCloseBtn = document.getElementById('popupClose');
if (popupCloseBtn) {
  popupCloseBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    controller.onDismiss();
  });
}

// ─── CTA click safety ───
// preventDefault stops "#" navigation; stopPropagation prevents bubble.
// Pointer-events on CTA children is handled by CSS so all clicks register on <a>.
window._ctaClickGuardUntil = 0;
[popupCta, popupCollabCta].forEach(btn => {
  if (!btn) return;
  btn.addEventListener('click', (e) => {
    e.preventDefault();
    e.stopPropagation();
    e.stopImmediatePropagation();
    window._ctaClickGuardUntil = Date.now() + 300;
  }, true);
  btn.addEventListener('pointerdown', (e) => {
    e.stopPropagation();
    window._ctaClickGuardUntil = Date.now() + 300;
  }, true);
});

// Document capture-phase guard — drops external clicks within suppression window.
// Excludes popup-internal clicks so × button and CTAs always work.
document.addEventListener('click', (e) => {
  if (Date.now() < window._ctaClickGuardUntil) {
    if (popup.contains(e.target)) return;
    e.stopImmediatePropagation();
    e.preventDefault();
  }
}, true);

// ─── Popup body wheel containment ───
popupBody.addEventListener('wheel', (e) => {
  const atTop = popupBody.scrollTop === 0;
  const atBottom = popupBody.scrollTop + popupBody.clientHeight >= popupBody.scrollHeight - 1;
  if ((atTop && e.deltaY < 0) || (atBottom && e.deltaY > 0)) return;
  e.stopPropagation();
}, { passive: true });

// ═══════════════════════════════════════════════════════════════
// FIRST-LOAD DEMONSTRATION PULSE
// Three random states gently glow once after page mount.
// Wordlessly teaches: "this map is alive."
// Disabled on reduced-motion.
// ═══════════════════════════════════════════════════════════════
if (!reduceMotion) {
  window.addEventListener('load', () => {
    setTimeout(() => {
      const allStates = Array.from(document.querySelectorAll('.state-group'));
      if (allStates.length === 0) return;
      
      // Pick 3 distinct states across the country (geographic spread)
      // Filter out tiny UTs which don't have visual presence
      const visibleStates = allStates.filter(g => {
        const id = g.id;
        return ![
          'state-chandigarh', 'state-delhi', 'state-dnhdd',
          'state-puducherry', 'state-lakshadweep'
        ].includes(id);
      });
      
      // Shuffle and pick 3
      const shuffled = visibleStates.sort(() => Math.random() - 0.5);
      const picked = shuffled.slice(0, 3);
      
      picked.forEach((state, i) => {
        setTimeout(() => {
          state.classList.add('first-pulse');
          setTimeout(() => state.classList.remove('first-pulse'), 1500);
        }, i * 350);
      });
    }, 600);  // small delay so user has settled their gaze
  });
}

})();
</script>



