<style>
.newrel {
  position: relative;
  width: 100%;
  height: 100vh;
  /* NOT 100dvh: Safari resizes dvh as the toolbar collapses mid-scroll,
     jolting this section as you cross it. Stable 100vh (matches hero fix). */
  font-family: "Outfit", sans-serif;
  color: #fff;
  overflow: hidden;
  isolation: isolate;
  contain: layout paint style;
  /* Continuous cosmic — same rgba pattern as other sections so the page-level
     cosmic-bg layer reads through. No more boxy left-side cosmic island. */
  background: rgba(8, 12, 18, 0.5);
}

/* Fade-on-pin · slow opacity crossfade only.
   No blur/filter (breaks 3D card transforms), no transform (causes layout shift).
   Stays above 0.85 so it reads as a soft pull, not a blink. */
.newrel__inner {
  transition: opacity 0.45s cubic-bezier(0.4, 0, 0.2, 1);
}
@media (prefers-reduced-motion: reduce) {
  .newrel__inner { transition: none; }
}

/* Hybrid background */
.newrel__bg-card {
  position: absolute;
  top: 0; left: 0;
  width: 50%;
  height: 100%;
  z-index: 0;
  pointer-events: none;
  overflow: hidden;
  /* Light wash so left side reads slightly darker than right (subtle composition
     anchor for the card). NO stars — cosmic-bg page layer provides those. */
  background:
    radial-gradient(ellipse 80% 100% at 30% 50%, rgba(2, 4, 10, 0.28) 0%, transparent 78%);
}

/* Local star drift/twinkle DISABLED — page-level cosmic-bg provides
   continuous stars across the entire homepage. Avoids "boxy cosmic" look. */
.newrel__bg-card::before,
.newrel__bg-card::after { display: none; }

@media (prefers-reduced-motion: reduce) {
  .newrel__bg-card::before,
  .newrel__bg-card::after { animation: none; }
}

.newrel__bg-cosmic {
  position: absolute;
  top: 0; right: 0;
  width: 50%;
  height: 100%;
  z-index: 0;
  pointer-events: none;
  background:
    radial-gradient(ellipse 80% 60% at 50% 30%, rgba(117,194,73,0.05) 0%, transparent 50%),
    radial-gradient(ellipse 60% 80% at 70% 70%, rgba(47,105,66,0.06) 0%, transparent 60%);
}

.newrel__bg-seam {
  position: absolute;
  top: 0; bottom: 0; left: 50%;
  width: 200px;
  margin-left: -100px;
  z-index: 1;
  pointer-events: none;
  background: linear-gradient(90deg, transparent 0%, rgba(13,17,23,0.4) 50%, transparent 100%);
  filter: blur(18px);
}

.newrel__divider {
  display: none;
}

/* Inner two-column layout — card-left, panels-right */
.newrel__inner {
  position: relative;
  width: 100%;
  height: 100%;
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: stretch;
  z-index: 3;
}

/* LEFT — card stage (fixed position within section, axis rotation only) */
/* Shared vertical inset — matches canonical section top padding (13rem
   like LIBS) so card top edge sits well below the floating nav, with
   the same visual rhythm as other sections. */
.newrel__card-stage {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  height: 100%;
  padding: clamp(6rem, 11vh, 10rem) 2rem clamp(3rem, 5vh, 4rem);
  position: relative;
  perspective: 1400px;
  box-sizing: border-box;
}

.newrel__smoke {
  position: absolute;
  top: 50%; left: 50%;
  width: 480px;
  height: 600px;
  transform: translate(-50%, -50%);
  pointer-events: none;
  z-index: 0;
}
.newrel__smoke::before,
.newrel__smoke::after {
  content: "";
  position: absolute;
  border-radius: 50%;
  filter: blur(16px);
  will-change: transform, opacity;
}
.newrel__smoke::before {
  width: 360px; height: 260px;
  top: 12%; left: -10%;
  background: radial-gradient(ellipse, rgba(47,105,66,0.32) 0%, rgba(117,194,73,0.08) 50%, transparent 70%);
  animation: nrSmokeA 12s ease-in-out infinite;
}
.newrel__smoke::after {
  width: 280px; height: 220px;
  bottom: 8%; right: -15%;
  background: radial-gradient(ellipse, rgba(117,194,73,0.18) 0%, rgba(187,214,122,0.05) 50%, transparent 70%);
  animation: nrSmokeB 14s ease-in-out infinite 2s;
}
@keyframes nrSmokeA {
  0%, 100% { transform: translate(0,0) scale(1); opacity: 0.55; }
  35% { transform: translate(15px,-18px) scale(1.1); opacity: 0.85; }
  65% { transform: translate(-10px,12px) scale(0.95); opacity: 0.45; }
}
@keyframes nrSmokeB {
  0%, 100% { transform: translate(0,0) scale(1); opacity: 0.5; }
  40% { transform: translate(-18px,-12px) scale(1.15); opacity: 0.78; }
  70% { transform: translate(12px,10px) scale(0.9); opacity: 0.4; }
}

/* Card */
.newrel__card {
  position: relative;
  height: calc(100vh - clamp(6rem, 11vh, 10rem) - clamp(3rem, 5vh, 4rem));
  height: calc(100dvh - clamp(6rem, 11vh, 10rem) - clamp(3rem, 5vh, 4rem));
  min-height: 280px;
  max-height: 480px;
  width: auto;
  max-width: 60%;
  aspect-ratio: 4 / 5;
  transform-style: preserve-3d;
  -webkit-transform-style: preserve-3d;
  transform: rotateY(0deg) translateZ(0.01px);
  transition: none;
  will-change: transform;
  contain: layout paint style;
  z-index: 1;
}

.newrel__card-face {
  position: absolute;
  inset: 0;
  border-radius: 18px;
  border: 1px solid rgba(255,255,255,0.10);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
  /* Safari fix — force GPU layer so the back face actually stays hidden
     instead of bleeding through as a mirror image */
  transform: translateZ(0);
  box-shadow:
    0 30px 80px rgba(0,0,0,0.55),
    0 0 30px rgba(117,194,73,0.05),
    inset 0 1px 0 rgba(255,255,255,0.08);
}
.newrel__card-face--back { transform: rotateY(180deg) translateZ(0); }

.newrel__card-art { position: absolute; inset: 0; z-index: 0; }
.newrel__card-art--voices {
  background:
    radial-gradient(ellipse at 30% 25%, rgba(117,194,73,0.18) 0%, transparent 55%),
    radial-gradient(ellipse at 75% 75%, rgba(47,105,66,0.28) 0%, transparent 55%),
    linear-gradient(160deg, #0f1a14 0%, #162218 50%, #0d1510 100%);
}
.newrel__card-art--tabla {
  background:
    radial-gradient(ellipse at 60% 30%, rgba(220,170,110,0.10) 0%, transparent 50%),
    radial-gradient(ellipse at 30% 70%, rgba(117,194,73,0.14) 0%, transparent 55%),
    linear-gradient(160deg, #1a1612 0%, #221a14 50%, #15110d 100%);
}

.newrel__card-face::after {
  content: "";
  position: absolute;
  top: 0; left: 0;
  width: 60%; height: 100%;
  background: linear-gradient(105deg,
    transparent 30%,
    rgba(255,255,255,0.04) 48%,
    rgba(255,255,255,0.08) 50%,
    rgba(255,255,255,0.04) 52%,
    transparent 70%);
  z-index: 2;
  pointer-events: none;
  animation: nrCardSheen 9s ease-in-out infinite;
}
@keyframes nrCardSheen { 0%,100%{transform:translateX(-133%)} 50%{transform:translateX(200%)} }

.newrel__card-body {
  position: relative;
  z-index: 3;
  margin-top: auto;
  padding: 1.5rem 1.4rem 1.6rem;
  background: linear-gradient(180deg, transparent 0%, rgba(0,0,0,0.55) 60%, rgba(0,0,0,0.85) 100%);
