/* RIGHT — internal scrolling panels container */
.newrel__panels-scroll {
  position: relative;
  height: 100%;
  overflow-y: auto;
  overflow-x: hidden;
  scrollbar-gutter: stable;
  /* No overscroll-behavior — JS handles boundary detection and release.
     Adding 'contain' here blocks the natural propagation that lets the
     page scroll past the section at boundaries. */
  scrollbar-width: thin;
  scrollbar-color: rgba(117,194,73,0.35) transparent;
  padding: 0;
}
.newrel__panels-scroll::-webkit-scrollbar { width: 5px; }
.newrel__panels-scroll::-webkit-scrollbar-track { background: transparent; }
.newrel__panels-scroll::-webkit-scrollbar-thumb { background: rgba(117,194,73,0.3); border-radius: 4px; }

.newrel__panel {
  height: 100vh;
  max-height: 100vh;
  display: flex;
  flex-direction: column;
  /* Top-align so eyebrow-to-nav distance matches card-to-nav distance */
  justify-content: flex-start;
  align-items: stretch;
  /* Matches card-stage padding — canonical 13rem top rhythm */
  padding:
    clamp(8rem, 13vh, 13rem)
    2rem
    clamp(3rem, 5vh, 4rem)
    2rem;
  box-sizing: border-box;
  /* Each panel is a one-screen "scene" — content longer than the available
     height scrolls inside its player-list (which is already scrollable). */
  overflow: hidden;
  flex-shrink: 0;
}

/* Inner content blocks — horizontally centered within the right column.
   Text + player-box span full content width, CTA keeps natural size. */
.newrel__panel > .newrel__eyebrow,
.newrel__panel > .newrel__panel-title,
.newrel__panel > .newrel__panel-desc,
.newrel__panel > .newrel__player-box {
  width: 100%;
  max-width: 540px;
  margin-left: auto;
  margin-right: auto;
}

/* CTA — fixed pill width, also horizontally centered as a block */
.newrel__panel > .newrel__cta {
