  overflow-y: auto;
  /* No overscroll-behavior / no scroll-behavior — JS at route() handles
     boundary detection via demoHasRunway() and writes scrollTop instantly.
     Both smooth-behavior and contain would fight that logic. */
  padding-right: 6px;
  scrollbar-width: thin;
  scrollbar-color: rgba(117,194,73,0.4) transparent;
  mask-image: linear-gradient(to bottom, #000 0%, #000 calc(100% - 18px), transparent 100%);
  -webkit-mask-image: linear-gradient(to bottom, #000 0%, #000 calc(100% - 18px), transparent 100%);
}
.newrel__player-list::-webkit-scrollbar { width: 5px; }
.newrel__player-list::-webkit-scrollbar-track { background: transparent; }
.newrel__player-list::-webkit-scrollbar-thumb { background: rgba(117,194,73,0.35); border-radius: 4px; }

.newrel__player-row {
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr) 50px;
  gap: 0.85rem;
  padding: 0.55rem 0.75rem;
  border-radius: 8px;
  background: rgba(255,255,255,0.018);
  border: 1px solid rgba(255,255,255,0.03);
  align-items: center;
  cursor: pointer;
  transition: all 0.3s cubic-bezier(0.22, 1, 0.36, 1);
}
.newrel__player-row:hover {
  border-color: rgba(117,194,73,0.18);
  background: rgba(117,194,73,0.025);
}
.newrel__player-row.is-playing {
  border-color: rgba(117,194,73,0.32);
  background: rgba(117,194,73,0.05);
  box-shadow: 0 6px 18px rgba(0,0,0,0.25), 0 0 14px rgba(117,194,73,0.05);
}

/* CSS-only waveform strip · sits at bottom of row, animates only when playing.
   18 thin bars rendered as a repeating gradient; the entire strip translates
   horizontally to simulate audio flow. Zero canvas, GPU-only. */
.newrel__player-row { position: relative; }

/* Animated EQ bars · 4 vertical bars next to the type label, visible only when playing.
   Tiny, decorative, communicates "this is the active track". */
.newrel__player-eq {
  display: inline-flex;
  align-items: flex-end;
  gap: 2px;
  height: 9px;
  margin-left: 0.4rem;
  opacity: 0;
  transition: opacity 0.3s ease;
  vertical-align: middle;
}
.newrel__player-eq span {
  width: 2px;
  background: var(--green-primary);
  border-radius: 1px;
  animation: eqBar 0.9s ease-in-out infinite;
  height: 30%;
}
.newrel__player-eq span:nth-child(1) { animation-delay: 0s;    --h: 60%; }
.newrel__player-eq span:nth-child(2) { animation-delay: 0.15s; --h: 90%; }
.newrel__player-eq span:nth-child(3) { animation-delay: 0.3s;  --h: 45%; }
.newrel__player-eq span:nth-child(4) { animation-delay: 0.45s; --h: 75%; }
@keyframes eqBar {
  0%, 100% { height: 25%; }
  50%      { height: var(--h, 80%); }
}
.newrel__player-row.is-playing .newrel__player-eq { opacity: 0.85; }
@media (prefers-reduced-motion: reduce) {
  .newrel__player-eq span { animation: none; height: 50%; }
}

.newrel__player-play {
  width: 36px; height: 36px;
  border-radius: 50%;
  background: rgba(255,255,255, 0.05);
  border: 1px solid rgba(255,255,255, 0.08);
  border-top-color: rgba(255,255,255, 0.14);
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
  cursor: pointer;
  position: relative;
  transition: all 0.35s cubic-bezier(0.22, 1, 0.36, 1);
  isolation: isolate;
}
.newrel__player-play::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--green-light), var(--green-primary));
  opacity: 0;
  transition: opacity 0.35s cubic-bezier(0.22, 1, 0.36, 1);
  z-index: -1;
}
.newrel__player-play:hover {
  border-color: transparent;
  transform: scale(1.06);
  box-shadow: 0 6px 18px rgba(0,0,0, 0.32), inset 0 1px 0 rgba(255,255,255, 0.22);
}
.newrel__player-play:hover::before { opacity: 1; }
.newrel__player-play:hover svg { fill: #0a0d12; }
/* Playing state · gradient fill + soft ring + pulse */
.newrel__player-row.is-playing .newrel__player-play {
  border-color: transparent;
  box-shadow: 0 6px 18px rgba(0,0,0, 0.35), inset 0 1px 0 rgba(255,255,255, 0.22);
}
.newrel__player-row.is-playing .newrel__player-play::before { opacity: 1; }
.newrel__player-row.is-playing .newrel__player-play svg { fill: #0a0d12; }
.newrel__player-row.is-playing .newrel__player-play::after {
  content: "";
  position: absolute;
  inset: -4px;
  border-radius: 50%;
  border: 1px solid rgba(117,194,73, 0.4);
  animation: playRing 1.8s ease-out infinite;
  pointer-events: none;
}
@keyframes playRing {
  0%   { transform: scale(0.95); opacity: 0.9; }
  100% { transform: scale(1.25); opacity: 0; }
}
.newrel__player-play svg { width: 11px; height: 11px; fill: #fff; transition: fill 0.3s ease; }

.newrel__player-info {
  display: flex; flex-direction: column;
  gap: 0.18rem;
  min-width: 0;
}
.newrel__player-row-type {
  font-size: 0.46rem;
