  font-size: 0.6rem;
  font-weight: 500;
  color: rgba(255,255,255,0.45);
  letter-spacing: 0.05em;
  text-align: right;
}

/* CTA */
.newrel__cta {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.7rem 1.6rem;
  border-radius: 50px;
  background: rgba(117, 194, 73, 0.05);
  border: 1px solid rgba(117, 194, 73, 0.2);
  color: rgba(255, 255, 255, 0.75);
  font-family: "Outfit", sans-serif;
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: none;
  text-decoration: none;
  cursor: pointer;
  transition: all 0.4s cubic-bezier(0.22, 1, 0.36, 1);
  position: relative;
  overflow: hidden;
  align-self: flex-start;
}
.newrel__cta::before {
  content: "";
  position: absolute;
  top: 0; left: -100%;
  width: 100%; height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.06), transparent);
  transition: left 0.6s cubic-bezier(0.22, 1, 0.36, 1);
}
.newrel__cta:hover {
  color: #fff;
  border-color: rgba(187, 214, 122, 0.4);
  background: rgba(117, 194, 73, 0.1);
  transform: translateY(-2px);
  box-shadow: 0 6px 22px rgba(0, 0, 0, 0.25), 0 0 16px rgba(117, 194, 73, 0.06);
}
.newrel__cta:hover::before { left: 100%; }
.newrel__cta-arrow { transition: transform 0.35s cubic-bezier(0.22, 1, 0.36, 1); }
.newrel__cta:hover .newrel__cta-arrow { transform: translateX(5px); }

/* Mobile */
@media (max-width: 1024px) {
  .newrel {
    height: auto;
    min-height: 100vh;
    /* Desktop sets overflow:hidden + contain for the scroll-hijack; on mobile
       that traps position:sticky (card scrolls off after <1 screen, leaving a
       void). Release both on mobile so the card stays pinned through the
       section. */
    overflow: visible;
    contain: none;
  }
  .newrel__bg-card {
    width: 100%; height: 50vh;
    background:
      radial-gradient(1px 1px at 18% 22%, rgba(255,255,255,0.55) 0%, transparent 100%),
