      radial-gradient(1px 1px at 8% 48%, rgba(255,255,255,0.4) 0%, transparent 100%),
      radial-gradient(1px 1px at 62% 56%, rgba(255,255,255,0.5) 0%, transparent 100%),
      radial-gradient(1.5px 1.5px at 88% 43%, rgba(187,214,122,0.45) 0%, transparent 100%),
      radial-gradient(1px 1px at 24% 72%, rgba(255,255,255,0.36) 0%, transparent 100%),
      radial-gradient(1px 1px at 78% 81%, rgba(255,255,255,0.42) 0%, transparent 100%),
      radial-gradient(1.5px 1.5px at 14% 32%, rgba(255,245,220,0.5) 0%, transparent 100%),
      radial-gradient(ellipse 55% 50% at 30% 45%, rgba(47,105,66,0.10) 0%, transparent 60%),
      radial-gradient(ellipse 45% 50% at 72% 68%, rgba(80,60,110,0.07) 0%, transparent 65%),
      radial-gradient(ellipse 65% 80% at 50% 50%, rgba(13,18,26,0.4) 0%, rgba(5,8,12,0.95) 60%, #02050a 100%),
      #02050a;
  }
  .newrel__bg-cosmic {
    width: 100%; top: auto; bottom: 0; height: 50vh;
  }
  .newrel__bg-seam {
    top: 50vh; bottom: auto;
    left: 0; right: 0; width: auto;
    height: 200px;
    margin: -100px 0 0 0;
    background: linear-gradient(180deg, transparent 0%, rgba(13,17,23,0.4) 50%, transparent 100%);
  }
  .newrel__divider { display: none; }
  .newrel__inner {
    grid-template-columns: 1fr;
    grid-template-rows: 45vh auto;
    height: auto;
  }
  .newrel__card-stage {
    position: sticky;
    top: 90px;                 /* clear the fixed nav (32px top + ~58px height) */
    height: calc(50vh - 90px); /* visible card band below the nav */
    padding: 1.5rem 2rem 2rem; /* match desktop side ratio (~2rem), trimmed top */
    background: linear-gradient(180deg, rgba(8,12,18,0.95) 0%, rgba(8,12,18,0.6) 80%, transparent 100%);
    z-index: 4;
  }
  .newrel__card { width: min(38vh, 60%); aspect-ratio: 4 / 5; }
  .newrel__smoke { width: 280px; height: 360px; }
  .newrel__panels-scroll {
    height: auto;
    overflow: visible;
    padding: 2rem 1.25rem 3rem;
    /* Card pins in the top band (sticky, below nav). Panels scroll UNDER it
       behind a SOLID surface so the flipping card never shows panel text
       through it. margin-top pushes the first panel below the pinned card
       band; opaque bg + z-index give the card a clean backing. */
    margin-top: 50vh;
    position: relative;
    z-index: 5;
    background: rgb(8, 12, 18);
  }
  .newrel__panel {
    min-height: 0;
    padding: 0;
    max-width: 100%;
