<script>
(function () {
  'use strict';

  var section = document.getElementById('new-releases');
  var card = document.getElementById('nrCard');
  var scrollEl = document.getElementById('nrPanelsScroll');
  if (!section || !card || !scrollEl) return;

  var prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (prefersReduced) return;

  function isMobile() { return window.innerWidth <= 1024; }

  /* ═══ CARD ROTATION based on internal scroll ═══ */
  var rotTicking = false;
  var lastAngle = -1;
  function updateCardRotation() {
    if (rotTicking) return;
    rotTicking = true;
    requestAnimationFrame(function(){
      rotTicking = false;
      /* Bail early when section is far off-screen — no point computing
         rotation for a card the user can't see. Keeps LIBS scroll smooth. */
      var rect = section.getBoundingClientRect();
      var vH = window.innerHeight;
      if (rect.bottom < -200 || rect.top > vH + 200) return;

      if (isMobile()) {
        /* Mobile uses discrete cinematic flips (cc-newrel-mobile-v2):
           scrubbing 180 degrees over a tall sheet left most scrolling
           inert. Clear stale inline so the class owns the angle. */
        if (card.style.transform) card.style.transform = '';
        lastAngle = -1;
        return;
      }
      /* Desktop: the card is sticky for the section's traverse; the flip
         maps to how far the section has scrolled past the viewport top. */
      var denom = Math.max(1, rect.height - vH);
      var progress = Math.max(0, Math.min(1, -rect.top / denom));
      var angle = Math.round(progress * 1800) / 10;
      if (angle === lastAngle) return;
      lastAngle = angle;
      card.style.transform = 'rotateY(' + angle + 'deg) translateZ(0.01px)';
    });
  }
  window.addEventListener('scroll', updateCardRotation, { passive: true });
  window.addEventListener('resize', updateCardRotation, { passive: true });
  updateCardRotation();

  /* ═══ MOTION v2 ═══
     The desktop wheel-router (pin/unpin state machine, per-frame native
     scrolling, Lenis stop/start, window-level non-passive listeners) is
     RETIRED. Page scroll is never intercepted. Desktop now uses the same
     native pattern mobile always used: sticky card, flip on section
     scroll progress, panels as normal flowing content. One scroll
     authority; identical logic in Chrome, Safari and Firefox. */

  /* MOTION v2 + AUDIO v1: the visual-only row toggle, its cc:media-stop
     listener and the panel auto-pause IO are superseded by the shared
     cc-demo-player.js engine (real audio, waveforms, continuous play,
     one-source-at-a-time on the same cc:media event bus). */
})();
</script>

