<script id="cc-scroll-hover-guard-js">
(function () {
  'use strict';
  var root = document.documentElement;
  var t = null;
  window.addEventListener('scroll', function () {
    if (t === null) root.classList.add('cc-scrolling');
    clearTimeout(t);
    t = setTimeout(function () {
      root.classList.remove('cc-scrolling');
      t = null;
    }, 120);
  }, { passive: true });
})();
</script>
<style id="cc-art-v1">
/* ═══════════════════════════════════════════════════════════════
   ART v1 · render optimization + scroll-driven cinematics
   Everything here is progressive enhancement behind @supports —
   browsers without support render the page exactly as before.
   ═══════════════════════════════════════════════════════════════ */

/* ── Render only what's near the viewport (big win on mobile).
      Excluded: hero/libs (above the fold), newrel (sticky child). ── */
@supports (content-visibility: auto) {
  /* Desktop excluded: estimated intrinsic sizes can nudge scroll height
     near New Releases — the reported Chrome glitch candidate. The win
     matters on mobile, where it stays. */
}


/* ── Scroll-driven cinematics (Chromium today; Safari/Firefox keep
      the IO reveal system — identical design, fewer flourishes).
      All transform/opacity only. Budget: these refine the EXISTING
      reveal pattern, they do not add a fourth motion pattern. ── */
@media (min-width: 1025px) and (prefers-reduced-motion: no-preference) {
  @supports (animation-timeline: view()) {

    /* 1 · The atlas recedes into the story as the hero exits —
           the landing page's opening scene cut. */
    .hero__map-stage {
      animation: cc-atlas-recede linear both;
      animation-timeline: view();
      animation-range: exit 0% exit 100%;
    }

    /* 2 · Featured-libraries ambient warmth drifts slower than the
           content — depth without parallaxing any text. */
    .libs__bleed, .libs__warmth {
      animation: cc-ambient-drift linear both;
      animation-timeline: view();
      animation-range: cover 0% cover 100%;
    }

    /* 3 · The New-Releases stage floats up to meet the catalogue —
           the "sections connect" moment. Background panels only. */
    .newrel__bg-card, .newrel__bg-cosmic {
      animation: cc-stage-rise linear both;
      animation-timeline: view();
      animation-range: entry 0% entry 70%;
    }
  }
}
@keyframes cc-atlas-recede {
  to { transform: scale(0.955) translateY(-14px); opacity: 0.45; }
}
@keyframes cc-ambient-drift {
  from { transform: translateY(36px); }
  to   { transform: translateY(-36px); }
}
@keyframes cc-stage-rise {
  from { transform: translateY(40px); opacity: 0.45; } /* softened: no black flash on arrival */
  to   { transform: translateY(0);    opacity: 1; }
}
