<style id="cc-state-browser">
/* ═══════════════════════════════════════════════════════════════
   MOBILE STATE BROWSER · bottom-sheet selector for the heritage map
   ≤768px only. Solid surface (no backdrop-filter — same call as the
   state popup). Transform/opacity motion only, canonical curve.
   ═══════════════════════════════════════════════════════════════ */
.msb { display: none; }
@media (max-width: 768px) {
  /* ── Direct-tap inflation ──────────────────────────────────────────
     .state-frag already has vector-effect: non-scaling-stroke, so
     stroke-width here is SCREEN pixels at any map scale. A transparent
     24px stroke adds a ~12px invisible tap halo around every state —
     Goa/Sikkim/NE states go from ~5-8px to ~28-32px effective targets.
     Where halos overlap at borders, the later DOM sibling wins: every
     tap lands on the state or its immediate neighbour, no dead zones.
     Stroke transitions dropped on mobile so the halo never flashes
     visible while animating to the active 0.7px colored stroke. */
  .state-frag {
    stroke-width: 24;
    transition: fill 0.45s cubic-bezier(0.4, 0, 0.2, 1);
  }


  .msb { display: block; margin: 1.1rem auto 0; text-align: center; }

  .msb__trigger {
