  }
  .msb__trigger:active { background: rgba(117,194,73,0.06); border-color: rgba(117,194,73,0.5); }
  .msb__trigger-arrow { font-size: 0.85rem; line-height: 1; transform: translateY(-1px); }

  .msb__scrim {
