    background: rgba(5,8,16,0.6);
    opacity: 0; transition: opacity 0.35s cubic-bezier(0.22, 1, 0.36, 1);
  }
  .msb__scrim.is-open { opacity: 1; }

  .msb__sheet {
    position: fixed; left: 0; right: 0; bottom: 0; z-index: 59;
    max-height: 72vh; display: flex; flex-direction: column;
    background: linear-gradient(180deg, rgba(21,27,35,0.99), rgba(13,17,23,0.99));
    border: 1px solid rgba(255,255,255,0.10);
    border-top-color: rgba(255,255,255,0.16);
    border-bottom: none;
    border-radius: 16px 16px 0 0;
