/* ── Safari/Firefox: drop SVG drop-shadow glows (expensive-props rule).
   polish.js tags <html class="no-glass-blur"> on those engines. The
   active state stays legible via .state-frag stroke + per-tile
   brightness; Chromium keeps the full glow. This is the click→popup
   delay fix for Safari: the double drop-shadow forced a main-thread
   rasterize of the state group + 4.8k-tile mosaic on every activation. */
html.no-glass-blur .map-stage:not([data-active-state]) .state-group:hover,
html.no-glass-blur .map-stage:not([data-active-state]) .state-group.hover-glow,
html.no-glass-blur .state-group.active,
html.no-glass-blur .map-stage[data-active-state] .tile-mosaic {
  filter: none !important;
}
html.no-glass-blur .state-group.first-pulse { animation: none !important; }

/* ── Mobile map enlargement ───────────────────────────────────────────
   India occupies only 800×909 of the 1000×1000 viewBox, and the mobile
   container was square while India is portrait. JS swaps the viewBox to
   the cropped landmass (80 26 840 949) at ≤768px; the container goes
   full-bleed portrait. Net: ~1.3× linear state size (~1.7× tap area). */

</style>
<script id="cc-state-browser-js">
(function () {
  'use strict';
  var root  = document.getElementById('msb-root');
  var trig  = document.getElementById('msb-trigger');
  var sheet = document.getElementById('msb-sheet');
  var scrim = document.getElementById('msb-scrim');
  var list  = document.getElementById('msb-list');
  var close = document.getElementById('msb-close');
  if (!root || !trig || !sheet || !scrim || !list || !close) return;

  /* Build list from the live map DOM — single source of truth */
  var ORDER = ['North', 'West', 'Central', 'East', 'Northeast', 'South', 'Islands'];
  var byRegion = {};
  document.querySelectorAll('g.state-group').forEach(function (g) {
    var r = g.dataset.region || 'Other';
    (byRegion[r] = byRegion[r] || []).push({
      id: g.id, name: g.dataset.name || g.id, type: g.dataset.type || 'State'
    });
  });
  var frag = document.createDocumentFragment();
  ORDER.concat(Object.keys(byRegion).filter(function (r) { return ORDER.indexOf(r) < 0; }))
    .forEach(function (region) {
      var items = byRegion[region];
      if (!items || !items.length) return;
      var lab = document.createElement('div');
      lab.className = 'msb__region';
      lab.textContent = region;
      frag.appendChild(lab);
      items.sort(function (a, b) { return a.name.localeCompare(b.name); })
        .forEach(function (it) {
          var b = document.createElement('button');
          b.type = 'button';
          b.className = 'msb__row';
          b.dataset.target = it.id;
          b.dataset.region = region;
          var isHQ = /delhi/i.test(it.name);
          b.innerHTML = '<span></span>' +
            (isHQ ? '<span class="msb__row-hq">Crypto Cipher HQ</span>' : '') +
            (it.type === 'UT' ? '<span class="msb__row-tag">UT</span>' : '');
          b.firstChild.textContent = it.name;
          frag.appendChild(b);
        });
    });
  list.appendChild(frag);

  var prevOverflow = '';
  function open() {
    sheet.hidden = false; scrim.hidden = false;
    prevOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    trig.setAttribute('aria-expanded', 'true');
    requestAnimationFrame(function () {
      sheet.classList.add('is-open'); scrim.classList.add('is-open');
    });
  }
  function shut() {
    sheet.classList.remove('is-open'); scrim.classList.remove('is-open');
    document.body.style.overflow = prevOverflow;
    trig.setAttribute('aria-expanded', 'false');
    setTimeout(function () { sheet.hidden = true; scrim.hidden = true; }, 380);
  }

  trig.addEventListener('click', function (e) { e.stopPropagation(); open(); });
  close.addEventListener('click', function (e) { e.stopPropagation(); shut(); });
  scrim.addEventListener('click', function (e) { e.stopPropagation(); shut(); });
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && !sheet.hidden) shut();
  });

  /* ── Mobile viewBox crop: scale India up to the landmass bounds ── */
  (function () {
    var svgEl = document.querySelector('svg.india-map');
    if (!svgEl) return;
    var FULL = '0 0 1000 1000', CROP = '-1 32 921 937' /* centroid-centered: mainland mass at 50% */;
    var mq = window.matchMedia('(max-width: 768px)');
    function apply() { svgEl.setAttribute('viewBox', mq.matches ? CROP : FULL); }
    if (mq.addEventListener) mq.addEventListener('change', apply);
    else if (mq.addListener) mq.addListener(apply);
    apply();
  })();

  list.addEventListener('click', function (e) {
    var row = e.target.closest('.msb__row');
    if (!row) return;
    e.stopPropagation(); /* keep the map's document-level dismiss handlers out */
    var g = document.getElementById(row.dataset.target);
    shut();
    if (!g) return;
    var ctrl = window.__ccMapController;
    requestAnimationFrame(function () {
      if (ctrl && typeof ctrl.onClickState === 'function') ctrl.onClickState(g);
      else g.querySelector('.state-frag') &&
        g.querySelector('.state-frag').dispatchEvent(new MouseEvent('click', { bubbles: false }));
    });
  });
})();
</script>

<style id="cc-newrel-mobile-v2">
/* NEW RELEASE · MOBILE v2
   Keep the card on discrete states on mobile so it never sits in a
   half-flipped jitter frame while the release sheet scrolls underneath. */
@media (prefers-reduced-motion: reduce) {
  .nr-m-progress b { transition: none !important; }
}

@media (max-width: 1024px) {
  .nr-m-progress {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    margin-top: 1rem;
    z-index: 2;
  }

  .nr-m-progress b {
    display: block;
    width: 26px;
    height: 3px;
    border-radius: 999px;
    background: rgba(255,255,255,0.16);
    transition:
      background 0.7s cubic-bezier(0.22, 1, 0.36, 1),
      transform 0.7s cubic-bezier(0.22, 1, 0.36, 1);
  }

  .nr-m-progress b.on {
    background: #BBD67A;
    transform: scaleX(1.05);
  }

  .newrel__card.nr-m-flip {
    transform: rotateY(180deg) translateZ(0.01px) !important;
  }
}
</style>
<script id="cc-newrel-mobile-v2-js">
(function () {
  'use strict';

  var mq = window.matchMedia('(max-width: 1024px)');
  var card = document.getElementById('nrCard');
  var stage = document.querySelector('.newrel__card-stage');
  var panels = document.querySelectorAll('.newrel__panel');
  if (!card || !stage || panels.length < 2) return;

  var existing = stage.querySelector('.nr-m-progress');
  if (existing) existing.remove();

  var prog = document.createElement('div');
  prog.className = 'nr-m-progress';
  prog.setAttribute('aria-hidden', 'true');

  for (var i = 0; i < panels.length; i++) {
    var bar = document.createElement('b');
    if (i === 0) bar.className = 'on';
    prog.appendChild(bar);
  }

  stage.appendChild(prog);
  var bars = prog.children;
  var active = 0;

  function setActive(idx) {
    if (idx === active) return;
    active = idx;
    card.classList.toggle('nr-m-flip', idx === 1);
    for (var i = 0; i < bars.length; i++) {
      bars[i].classList.toggle('on', i === idx);
    }
  }

  if ('IntersectionObserver' in window) {
    var io = new IntersectionObserver(function (entries) {
      if (!mq.matches) return;
      entries.forEach(function (entry) {
        if (entry.isIntersecting) {
          setActive(Array.prototype.indexOf.call(panels, entry.target));
        }
      });
    }, { rootMargin: '-55% 0px -30% 0px', threshold: 0 });

    Array.prototype.forEach.call(panels, function (panel) {
      io.observe(panel);
    });
  }

  if (mq.addEventListener) {
    mq.addEventListener('change', function (event) {
      if (!event.matches) {
        card.classList.remove('nr-m-flip');
      }
    });
  }

  document.querySelectorAll('.newrel__player-list').forEach(function (el) {
    el.setAttribute('data-lenis-prevent', '');
  });
})();
</script>

