}

/* BG */
.collab__bg{position:absolute;inset:0;z-index:0;pointer-events:none}
.collab__bg::before{content:"";position:absolute;inset:0;opacity:.04;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.7' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");background-size:200px}
.collab__bg::after{content:"";position:absolute;inset:0;background:radial-gradient(ellipse at 15% 50%,rgba(47,105,66,.12) 0%,transparent 55%),radial-gradient(ellipse at 85% 40%,rgba(117,194,73,.05) 0%,transparent 50%)}

/* Waves — vertical light streaks, ambient depth */
.collab__waves{position:absolute;inset:0;z-index:0;pointer-events:none;overflow:hidden}
.collab__waves b{position:absolute;bottom:0;width:1px;height:60vh;background:linear-gradient(180deg,transparent,rgba(255,255,255,.04),transparent);animation:colW var(--d,15s) ease-in-out infinite;opacity:0;will-change:transform,opacity}
@keyframes colW{0%{transform:translateY(100%);opacity:0}15%{opacity:.3}85%{opacity:.3}100%{transform:translateY(-100%);opacity:0}}
.collab__waves b:nth-child(1){left:8%;--d:14s}
.collab__waves b:nth-child(2){left:22%;--d:18s;animation-delay:3s}
.collab__waves b:nth-child(3){left:45%;--d:16s;animation-delay:1.5s}
.collab__waves b:nth-child(4){left:68%;--d:20s;animation-delay:5s}
.collab__waves b:nth-child(5){left:88%;--d:13s;animation-delay:2s}

/* Layout — 50/50 split, canonical max-width */
.collab__inner{
  position:relative;z-index:2;width:100%;
  max-width:1100px;margin:0 auto;padding:0 3rem;
  display:grid;
  grid-template-columns:1fr 1fr;
