.collab__card:nth-child(4){transition-delay:.42s}

/* Sweep */
.collab__card::after{content:"";position:absolute;top:0;left:-100%;width:50%;height:100%;background:linear-gradient(105deg,transparent 30%,rgba(255,255,255,.015) 45%,rgba(255,255,255,.04) 50%,rgba(255,255,255,.015) 55%,transparent 70%);z-index:5;pointer-events:none;animation:cSw 8s ease-in-out infinite var(--sw,0s)}
