@keyframes cSw{0%,100%{left:-100%}50%{left:120%}}

/* Glossy */
.collab__card::before{content:"";position:absolute;inset:0;border-radius:14px;background:linear-gradient(160deg,rgba(255,255,255,.06) 0%,transparent 35%,transparent 65%,rgba(255,255,255,.02) 100%);z-index:1;pointer-events:none}

/* Hover */
.collab__card:hover{border-color:rgba(117,194,73,.15);box-shadow:0 18px 55px rgba(0,0,0,.35),0 0 22px rgba(117,194,73,.04),inset 0 1px 0 rgba(255,255,255,.06)}

/* Glow follow */
.collab__glow{position:absolute;width:140px;height:140px;border-radius:50%;background:radial-gradient(circle,rgba(117,194,73,.06) 0%,transparent 70%);pointer-events:none;z-index:0;opacity:0;transform:translate(-50%,-50%);transition:opacity .3s ease}
