<script>
(function(){
  'use strict';
  var sec = document.getElementById('collaboration');
  if (!sec) return;

  function show() { sec.classList.add('visible'); }
  if ('IntersectionObserver' in window) {
    var io = new IntersectionObserver(function(e) {
      if (e[0].isIntersecting) { show(); io.disconnect(); }
    }, { threshold: 0.1 });
    io.observe(sec);
  } else { show(); }
  setTimeout(function() { if (!sec.classList.contains('visible')) show(); }, 400);

  // Skip 3D tilt + glow follow if reduced-motion preferred
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;

  sec.querySelectorAll('.collab__card').forEach(function(card) {
    var glow = card.querySelector('.collab__glow');
    card.addEventListener('mousemove', function(e) {
      var r = card.getBoundingClientRect();
      var x = (e.clientX - r.left) / r.width - .5;
      var y = (e.clientY - r.top) / r.height - .5;
      if (glow) { glow.style.left = (e.clientX - r.left) + 'px'; glow.style.top = (e.clientY - r.top) + 'px'; }
      card.style.transform = 'rotateX(' + (-y * 4) + 'deg) rotateY(' + (x * 4) + 'deg) translateY(-3px) scale(1.01)';
    }, { passive: true });
    card.addEventListener('mouseleave', function() { card.style.transform = ''; });
  });

  var cta = sec.querySelector('.collab__cta');
  if (cta) {
    cta.addEventListener('mousemove', function(e) {
      var r = cta.getBoundingClientRect();
      cta.style.transform = 'translate(' + ((e.clientX - r.left - r.width/2) * .1) + 'px,' + ((e.clientY - r.top - r.height/2) * .1) + 'px)';
    }, { passive: true });
    cta.addEventListener('mouseleave', function() { cta.style.transform = ''; });
  }
})();
</script>
