.hvid__grain {
  position: absolute; inset: 0;
  z-index: 0; pointer-events: none; opacity: 0.045;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.8' numOctaves='5' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
  background-size: 180px;
}

.hvid__glow { position: absolute; inset: 0; z-index: 0; pointer-events: none; }
.hvid__glow::before {
  content:""; position:absolute; top:5%; left:50%;
  width:90vw; height:70vh; max-width:1300px;
  transform: translateX(-50%);
  background:
    radial-gradient(ellipse at 35% 40%, rgba(47,105,66,0.12) 0%, transparent 50%),
    radial-gradient(ellipse at 65% 60%, rgba(75,145,65,0.08) 0%, transparent 45%);
  animation: hvNebula 16s ease-in-out infinite;
  will-change: transform, opacity;
}
.hvid__glow::after {
  content:""; position:absolute; bottom:0; left:50%;
  width:70vw; height:50vh;
  transform: translateX(-50%);
  background:
    radial-gradient(ellipse at 40% 50%, rgba(187,214,122,0.05) 0%, transparent 50%),
    radial-gradient(ellipse at 70% 30%, rgba(47,105,66,0.06) 0%, transparent 45%);
  animation: hvNebula 20s ease-in-out infinite reverse;
  will-change: transform, opacity;
}
@keyframes hvNebula { 0%,100%{opacity:.4;transform:translateX(-50%) scale(1)} 50%{opacity:.8;transform:translateX(-50%) scale(1.04)} }

.hvid__vignette {
  position: absolute; inset: 0;
  z-index: 0; pointer-events: none;
  background: radial-gradient(ellipse at 50% 50%, transparent 35%, rgba(6,9,16,0.45) 100%);
}

.hvid__dust { position: absolute; inset: 0; z-index: 1; pointer-events: none; }
.hvid__dust i {
  position: absolute; border-radius: 50%; opacity: 0;
  animation: hvDust linear infinite;
  will-change: transform, opacity;
}
.hvid__dust i:nth-child(1){left:8%;width:2px;height:2px;background:rgba(187,214,122,0.25);animation-duration:20s}
.hvid__dust i:nth-child(2){left:22%;width:1.5px;height:1.5px;background:rgba(255,255,255,0.2);animation-duration:16s;animation-delay:3s}
.hvid__dust i:nth-child(3){left:40%;width:2px;height:2px;background:rgba(117,194,73,0.2);animation-duration:22s;animation-delay:1s}
.hvid__dust i:nth-child(4){left:58%;width:1.5px;height:1.5px;background:rgba(187,214,122,0.18);animation-duration:18s;animation-delay:5s}
.hvid__dust i:nth-child(5){left:75%;width:2px;height:2px;background:rgba(255,255,255,0.15);animation-duration:15s;animation-delay:2s}
.hvid__dust i:nth-child(6){left:90%;width:1px;height:1px;background:rgba(117,194,73,0.22);animation-duration:24s;animation-delay:4s}
.hvid__dust i:nth-child(7){left:35%;width:1px;height:1px;background:rgba(255,255,255,0.18);animation-duration:19s;animation-delay:6s}
.hvid__dust i:nth-child(8){left:65%;width:1.5px;height:1.5px;background:rgba(187,214,122,0.15);animation-duration:21s;animation-delay:1.5s}
@keyframes hvDust {
  0%{transform:translateY(100vh) translateX(0);opacity:0}
  8%{opacity:.35}
  50%{transform:translateY(40vh) translateX(15px);opacity:.25}
  92%{opacity:.3}
  100%{transform:translateY(-10vh) translateX(-10px);opacity:0}
}

/* ─── Video frame ─── */
.hvid__frame {
  position: relative;
  z-index: 2;
  width: 78vw;
  max-width: 1280px;
  aspect-ratio: 16 / 9;
  border-radius: 28px;
  overflow: hidden;
  cursor: pointer;
  transition: transform 0.6s cubic-bezier(0.22,1,0.36,1), box-shadow 0.6s ease;
  box-shadow:
    0 30px 80px rgba(0,0,0,0.6),
    0 8px 30px rgba(0,0,0,0.4),
    0 0 0 1px rgba(255,255,255,0.04),
    0 0 60px rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.06);
  opacity: 0;
  transform: translateY(50px) scale(0.97);
}
.hvid__frame.is-visible {
  opacity: 1;
  transform: translateY(0) scale(1);
  transition: opacity 1s cubic-bezier(0.22,1,0.36,1), transform 1.2s cubic-bezier(0.22,1,0.36,1);
}
.hvid__frame:hover {
  box-shadow:
    0 40px 100px rgba(0,0,0,0.7),
    0 12px 40px rgba(0,0,0,0.5),
    0 0 0 1px rgba(255,255,255,0.08),
    0 0 80px rgba(255,255,255,0.04);
}
.hvid__frame::before {
  content:""; position:absolute; inset:-1px;
  border-radius: 29px;
  background: linear-gradient(160deg, rgba(255,255,255,0.10) 0%, transparent 30%, transparent 70%, rgba(255,255,255,0.04) 100%);
  z-index: 10; pointer-events: none;
  opacity: 1;
  transition: opacity 0.5s cubic-bezier(0.22,1,0.36,1);
}

.hvid__highlight {
  position:absolute; width:300px; height:300px; border-radius:50%;
  background: radial-gradient(circle, rgba(255,255,255,0.06) 0%, transparent 70%);
  z-index: 5; pointer-events: none; opacity: 0;
  transform: translate(-50%, -50%);
  transition: opacity 0.4s ease;
}
.hvid__frame:hover .hvid__highlight { opacity: 1; }

/* ─── Poster image — static gradient backdrop ─── */
.hvid__poster-art {
  position: absolute; inset: 0;
  z-index: 1;
  background:
    radial-gradient(ellipse at 30% 25%, rgba(255,255,255,0.06) 0%, transparent 55%),
    radial-gradient(ellipse at 75% 70%, rgba(120,130,150,0.10) 0%, transparent 50%),
    linear-gradient(160deg, #1c2128 0%, #14181f 50%, #0a0e14 100%);
}
.hvid__poster-art::after {
  content:""; position:absolute; inset:0;
  background: linear-gradient(180deg, rgba(6,9,16,0.25) 0%, rgba(6,9,16,0.55) 60%, rgba(6,9,16,0.85) 100%);
}

/* ─── Play button ─── */
.hvid__play {
  position: absolute;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  width: 88px; height: 88px;
  border-radius: 50%;
  background: rgba(255,255,255,0.06);
  backdrop-filter: blur(16px); -webkit-backdrop-filter: blur(16px);
  border: 1px solid rgba(255,255,255, 0.10);
  border-top-color: rgba(255,255,255, 0.18);
  display: flex; align-items: center; justify-content: center;
  cursor: pointer;
  z-index: 8;
  transition: transform 0.4s cubic-bezier(0.22,1,0.36,1),
              background 0.4s cubic-bezier(0.22,1,0.36,1),
              border-color 0.4s cubic-bezier(0.22,1,0.36,1),
              box-shadow 0.4s cubic-bezier(0.22,1,0.36,1);
  box-shadow: 0 8px 28px rgba(0,0,0, 0.35), inset 0 1px 0 rgba(255,255,255,0.08);
}
.hvid__play:hover {
  transform: translate(-50%, -50%) scale(1.04);
  background: rgba(255,255,255,0.1);
  border-color: rgba(212, 166, 86, 0.45);
  box-shadow: 0 12px 36px rgba(0,0,0, 0.4), 0 0 32px rgba(212, 166, 86, 0.18), inset 0 1px 0 rgba(255,255,255,0.12);
}
.hvid__play svg {
  width: 26px; height: 26px;
  fill: rgba(255,255,255, 0.92);
  margin-left: 4px;
  transition: fill 0.3s ease;
}
.hvid__play:hover svg { fill: var(--heritage-gold); }


/* ─── Text overlay ─── */
.hvid__text {
  position: absolute;
  bottom: 0; left: 0; right: 0;
  z-index: 9;
  padding: 2.5rem 3rem;
  background: linear-gradient(0deg, rgba(6,9,16,0.85) 0%, rgba(6,9,16,0.4) 60%, transparent 100%);
}
.hvid__text-label {
  display: inline-flex; align-items: center; gap: 0.5rem;
  font-size: 0.6rem; font-weight: 600;
  letter-spacing: 0.22em; text-transform: uppercase;
  color: var(--heritage-gold);
  margin-bottom: 0.7rem;
  opacity: 0; transform: translateY(15px);
  transition: all 0.8s cubic-bezier(0.22,1,0.36,1) 0.3s;
}
.hvid__text-label::before {
  content:""; width: 18px; height: 1px;
  background: linear-gradient(90deg, var(--heritage-gold-soft), transparent);
}
.hvid__text-heading {
  font-family: "Playfair Display", serif;
  font-size: clamp(1.8rem, 3vw, 2.8rem);
  font-weight: 900; line-height: 1.15;
  letter-spacing: -0.01em;
  color: #fff;
  margin-bottom: 0.5rem;
  padding-bottom: 0.15rem;
  max-width: 600px;
  opacity: 0; transform: translateY(20px);
  transition: all 0.9s cubic-bezier(0.22,1,0.36,1) 0.45s;
}
.hvid__text-heading em {
  font-style: normal;
  display: inline-block;
  background: linear-gradient(135deg, #ffffff 0%, #BBD67A 55%, #75C249 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  padding-bottom: 0.1em;
}
.hvid__text-body {
  font-size: clamp(0.72rem, 1.1vw, 0.88rem);
  font-weight: 300; line-height: 1.7;
  color: rgba(255,255,255,0.5);
  max-width: 520px;
  opacity: 0; transform: translateY(15px);
  transition: all 0.8s cubic-bezier(0.22,1,0.36,1) 0.6s;
}
.hvid__frame.is-visible .hvid__text-label,
.hvid__frame.is-visible .hvid__text-heading,
.hvid__frame.is-visible .hvid__text-body { opacity: 1; transform: translateY(0); }

.hvid__ctas {
  display: flex; align-items: center;
  gap: 1rem;
  margin-top: 1.2rem;
  opacity: 0;
  transform: translateY(15px);
  transition: all 0.8s cubic-bezier(0.22,1,0.36,1) 0.75s;
  position: relative; z-index: 10;
}
.hvid__frame.is-visible .hvid__ctas { opacity: 1; transform: translateY(0); }

.hvid__cta-primary {
  position: relative;
  display: inline-flex; align-items: center; justify-content: center;
  gap: 0.55rem;
  padding: 0.8rem 1.7rem;
  border-radius: 50px;
  background: linear-gradient(180deg, rgba(255,255,255,0.06), rgba(255,255,255,0.02));
  border: 1px solid rgba(255, 255, 255, 0.14);
  color: rgba(255,255,255,0.92);
  font-family: "Outfit", sans-serif;
  font-size: 0.72rem; font-weight: 600;
  letter-spacing: 0.08em;
  text-decoration: none; cursor: pointer; overflow: hidden;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.08),
    inset 0 -1px 0 rgba(0, 0, 0, 0.2),
    0 4px 16px rgba(0, 0, 0, 0.3);
  transition:
    background 0.45s cubic-bezier(0.22, 1, 0.36, 1),
    border-color 0.45s cubic-bezier(0.22, 1, 0.36, 1),
    color 0.45s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 0.45s cubic-bezier(0.22, 1, 0.36, 1),
    transform 0.45s cubic-bezier(0.22, 1, 0.36, 1);
}
.hvid__cta-primary::before {
  content: "";
  position: absolute; top: 0; left: 0; right: 0; height: 1px;
  background: linear-gradient(90deg, transparent 10%, rgba(255, 255, 255, 0.45) 50%, transparent 90%);
  z-index: 2; pointer-events: none;
}
.hvid__cta-primary:hover {
  color: #fff;
  border-color: rgba(212, 166, 86, 0.4);
  background: linear-gradient(180deg, rgba(255,255,255,0.09), rgba(255,255,255,0.03));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.16),
    inset 0 -1px 0 rgba(0, 0, 0, 0.25),
    inset 0 0 0 1px rgba(255, 255, 255, 0.04),
    0 6px 18px rgba(0, 0, 0, 0.4),
    0 18px 40px rgba(0, 0, 0, 0.25);
}
.hvid__cta-primary::after {
  content:""; position:absolute; top:0; left:-100%; width:60%; height:100%;
  background: linear-gradient(105deg, transparent 30%, rgba(255,255,255,0.06) 46%, rgba(255,255,255,0.22) 50%, rgba(255,255,255,0.06) 54%, transparent 70%);
  z-index: 1;
  transition: left 0.85s cubic-bezier(0.22,1,0.36,1);
}
.hvid__cta-primary:hover::after { left: 140%; }
.hvid__cta-arrow{
  position:relative;z-index:2;
  display:inline-block;
  transition:transform .35s cubic-bezier(.22,1,.36,1);
}
.hvid__cta-primary .hvid__cta-text { position: relative; z-index: 2; }

.hvid__cta-secondary {
  position: relative;
  display: inline-flex; align-items: center; justify-content: center;
  gap: 0.55rem;
  padding: 0.8rem 1.7rem;
  border-radius: 50px;
  background: rgba(255, 255, 255, 0.02);
  backdrop-filter: blur(14px) saturate(1.1);
  -webkit-backdrop-filter: blur(14px) saturate(1.1);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: rgba(255, 255, 255, 0.7);
  font-family: "Outfit", sans-serif;
  font-size: 0.72rem; font-weight: 600;
  letter-spacing: 0.08em;
  text-decoration: none; cursor: pointer; overflow: hidden;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.05),
    inset 0 -1px 0 rgba(0, 0, 0, 0.15),
    0 4px 14px rgba(0, 0, 0, 0.25);
  transition:
    background 0.5s cubic-bezier(0.22, 1, 0.36, 1),
    border-color 0.5s cubic-bezier(0.22, 1, 0.36, 1),
    color 0.5s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 0.5s cubic-bezier(0.22, 1, 0.36, 1),
    transform 0.55s cubic-bezier(0.22, 1, 0.36, 1),
    backdrop-filter 0.5s cubic-bezier(0.22, 1, 0.36, 1);
}
.hvid__cta-secondary .hvid__cta-text { position: relative; z-index: 2; }
.hvid__cta-secondary:hover {
  color: #fff;
  border-color: rgba(212, 166, 86, 0.4);
  background: rgba(255, 255, 255, 0.04);
  backdrop-filter: blur(16px) saturate(1.3);
  -webkit-backdrop-filter: blur(16px) saturate(1.3);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.12),
    inset 0 -1px 0 rgba(0, 0, 0, 0.2),
    inset 0 0 0 1px rgba(255, 255, 255, 0.04),
    0 6px 18px rgba(0, 0, 0, 0.35),
    0 14px 32px rgba(0, 0, 0, 0.2);
}
.hvid__cta-secondary::after {
  content:""; position:absolute; top:0; left:-100%; width:60%; height:100%;
  background: linear-gradient(105deg, transparent 30%, rgba(255,255,255,0.06) 50%, transparent 70%);
  z-index: 1;
  transition: left 0.85s cubic-bezier(0.22,1,0.36,1);
}
.hvid__cta-secondary:hover::after { left: 140%; }

.hvid__inner-vig {
  position: absolute; inset: 0;
  z-index: 3; pointer-events: none;
  background: radial-gradient(ellipse at 50% 50%, transparent 40%, rgba(6,9,16,0.3) 100%);
  border-radius: 28px;
}

/* ─── Inline player — fades in over poster on play ─── */
.hvid__player {
  position: absolute; inset: 0;
  z-index: 4;
  opacity: 0;
  pointer-events: none;
  /* Match theme — dark cosmic, not generic black */
  background: #0d1117;
  /* Inherit frame's rounded corners so iframe is clipped */
  border-radius: 28px;
  overflow: hidden;
  isolation: isolate;
  -webkit-transform: translateZ(0);
  transform: translateZ(0);
  transition: opacity 0.6s cubic-bezier(0.22,1,0.36,1);
}
.hvid__frame.is-playing .hvid__player {
  opacity: 1;
  pointer-events: auto;
}
.hvid__player iframe,
.hvid__player > div {
  width: 100% !important;
  height: 100% !important;
  border: 0;
  display: block;
  border-radius: inherit;
}

/* Close button — top-right of player, fades in with playback */
.hvid__close {
  position: absolute;
  top: 1rem; right: 1rem;
  width: 36px; height: 36px;
  border-radius: 50%;
  background: rgba(13,17,23,0.65);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border: 1px solid rgba(255,255,255,0.10);
  color: rgba(255,255,255,0.85);
  display: flex; align-items: center; justify-content: center;
  cursor: pointer;
  z-index: 12;
  opacity: 0;
  pointer-events: none;
  transition:
    opacity 0.8s cubic-bezier(0.22,1,0.36,1) 0.4s,
    background 0.3s ease,
    border-color 0.3s ease,
    transform 0.3s cubic-bezier(0.22,1,0.36,1);
}
.hvid__frame.is-playing .hvid__close {
  opacity: 1;
  pointer-events: auto;
}
.hvid__close:hover {
  background: rgba(13,17,23,0.85);
  border-color: rgba(187,214,122,0.35);
  color: #BBD67A;
  transform: rotate(90deg);
}
.hvid__close svg { width: 14px; height: 14px; pointer-events: none; }

/* When playing: fade poster, play button, text, vignette */
.hvid__frame.is-playing .hvid__poster-art,
.hvid__frame.is-playing .hvid__play,
.hvid__frame.is-playing .hvid__text,
.hvid__frame.is-playing .hvid__inner-vig,
.hvid__frame.is-playing .hvid__highlight {
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.5s cubic-bezier(0.22,1,0.36,1);
}
/* Glass-edge overlay sits above the player (z-index 10) with a 1px-offset
   radius — during playback it mismatches the video edge (visible on Firefox).
   Drop it while playing so the rounded video clip stays clean. */
.hvid__frame.is-playing::before { opacity: 0; }
.hvid__frame.is-playing { cursor: default; }
.hvid__frame.is-playing:hover { transform: none; }

/* ═══ Responsive ═══ */
@media (min-width: 2560px) {
  .hvid { padding: 8rem 3rem; }
  .hvid__play { width: 100px; height: 100px; }
  .hvid__play svg { width: 30px; height: 30px; }
  .hvid__text { padding: 3.5rem 4rem; }
}
@media (max-width: 1024px) {
  .hvid__frame { width: 90vw; border-radius: 22px; }
  .hvid__frame::before { border-radius: 23px; }
  .hvid__player, .hvid__player iframe, .hvid__player > div { border-radius: 22px; }
  .hvid__text { padding: 2rem 2.2rem; }
  .hvid__play { width: 76px; height: 76px; }
  .hvid__play svg { width: 22px; height: 22px; }
}



@media (prefers-reduced-motion: reduce) {
  .hvid__dust i, .hvid__glow::before, .hvid__glow::after,
  .hvid__play, .hvid__play::before {
    animation: none !important;
  }
  .hvid__frame { opacity: 1 !important; transform: none !important; }
}
</style>

<section class="hvid" id="heritage" aria-labelledby="hvid-heading">
  <div class="hvid__grain"></div>
  <div class="hvid__glow"></div>
  <div class="hvid__vignette"></div>
  <div class="hvid__dust"><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div>

  <div class="hvid__frame" id="hvid-frame" data-yt-id="wb_wm1eAh3I" role="button" tabindex="0" aria-label="Play heritage film">
    <div class="hvid__highlight" id="hvid-hl"></div>
    <div class="hvid__poster-art"></div>
    <div class="hvid__inner-vig"></div>

    <button class="hvid__play" id="hvid-play" type="button" aria-label="Play heritage film">
      <svg viewBox="0 0 24 24" aria-hidden="true"><polygon points="6 3 20 12 6 21 6 3"/></svg>
    </button>

    <div class="hvid__text">
      <div class="hvid__text-label" data-reveal data-reveal-group="hvid-head">Our Heritage</div>
      <h3 class="hvid__text-heading" id="hvid-heading" data-reveal data-reveal-group="hvid-head">The Sound of a Timeless <em>Civilization</em></h3>
      <p class="hvid__text-body hvid__text-body--lead" data-reveal data-reveal-group="hvid-head"><span class="leadin">Rooted in the Vedas,</span> codified in the <em>Natya Shastra</em>. The world's oldest unbroken musical tradition — Hindustani and Carnatic, recorded as they're meant to be heard.</p>
      <div class="hvid__ctas">
        <a href="/heritage" class="hvid__cta-primary" id="hvid-cta-1"><span class="hvid__cta-text">Heritage Archives</span><span class="hvid__cta-arrow">→</span></a>
        <a href="/heritage/film" class="hvid__cta-secondary" id="hvid-cta-2"><span class="hvid__cta-text">Watch Featured Film</span><span class="hvid__cta-arrow">→</span></a>
      </div>
    </div>

    <!-- Inline player container — iframe injects here on play -->
    <div class="hvid__player" id="hvid-player"></div>

    <!-- Close button — visible only during playback -->
    <button class="hvid__close" id="hvid-close" type="button" aria-label="Close video">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M18 6L6 18M6 6l12 12"/></svg>
    </button>
  </div>
</section>

<script>
(function(){
  'use strict';
  var section = document.getElementById('heritage');
  var frame   = document.getElementById('hvid-frame');
  var playBtn = document.getElementById('hvid-play');
  var hl      = document.getElementById('hvid-hl');
  var playerHost = document.getElementById('hvid-player');
  if (!frame) return;

  var ytId = frame.getAttribute('data-yt-id') || '';
  var reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var ytPlayer = null;          // YouTube Player instance
  var ytApiLoading = false;     // single-load guard
  var pendingPlay = false;

  /* ── Poster thumbnail from YouTube ──
     Show the real video thumbnail from the existing data-yt-id AND keep the
     brand glow on top. Layer order (front → back):
       1) green/gold radial glows  (semi-transparent — photo shows through)
       2) a light dark scrim       (keeps white play-button + text legible)
       3) the YouTube photo        (the actual base image)
     The original CSS ended in a SOLID dark linear-gradient that hid any image
     painted behind it — that opaque layer is intentionally dropped here.
     No API key — i.ytimg.com is the public CDN. maxresdefault only exists for
     HD uploads; when missing YouTube serves a 120x90 grey placeholder (not a
     404), detected by natural width, then we fall back to hqdefault. */
  (function loadPosterThumb(){
    var poster = frame.querySelector('.hvid__poster-art');
    if (!poster || !ytId) return;
