  function hideNav() {
    var nav = document.getElementById('cc-nav');
    if (nav) nav.classList.add('cc-nav--cinematic');
  }
  function showNav() {
    var nav = document.getElementById('cc-nav');
    if (!nav) return;
    /* Keep the slow transition alive while the class is being removed */
    nav.classList.add('cc-nav--cinematic-returning');
    nav.classList.remove('cc-nav--cinematic');
