  function unlockPageScroll() {}

  /* AUDIO v2: heritage video joins the one-source-at-a-time bus */
  document.addEventListener('cc:media-start', function (e) {
    var d = e && e.detail || {};
    if (d.owner !== 'hvid') stopPlayback();
  });
