    document.head.appendChild(tag);
    window.onYouTubeIframeAPIReady = function(){ callback(); };
  }

  /* ── Build player inside frame ── */
  function buildPlayer() {
    if (ytPlayer) { ytPlayer.playVideo(); document.dispatchEvent(new CustomEvent('cc:media-start',{detail:{owner:'hvid'}})); return; }
    /* Container element for YT API to replace */
    var holder = document.createElement('div');
    holder.id = 'hvid-yt-' + Date.now();
    playerHost.appendChild(holder);

    ytPlayer = new window.YT.Player(holder.id, {
      videoId: ytId,
      playerVars: {
        autoplay: 1,
        rel: 0,
        modestbranding: 1,
        playsinline: 1,
        color: 'white',
        iv_load_policy: 3,
        list: 'PL-qjKbqchCDaJULWtkLYBY83HIr2d_sYB'
      },
      events: {
        onReady: function(e){ e.target.playVideo(); },
        onStateChange: function(e){
          var YTState = window.YT.PlayerState;
          if (e.data === YTState.PLAYING) {
            frame.classList.add('is-playing');
