  /* ── Start playback ── */
  function startPlayback() {
    if (!ytId) return;
    if (pendingPlay) return;
    pendingPlay = true;

    /* Center the frame in viewport before locking page scroll. */
    var frameRect = frame.getBoundingClientRect();
    var frameCenterY = frameRect.top + window.scrollY + frameRect.height / 2;
    var targetScrollY = frameCenterY - window.innerHeight / 2;
    targetScrollY = Math.max(0, targetScrollY);

    function commitPlay() {
