     sub-pixel border flicker on Firefox, and the frame should read as a
     still glass panel (no movement) per design direction. ── */

  /* ── Glass CTAs: no positional movement (magnetic effect removed).
     Hover response is surface-only (border/glow/sheen) via CSS. ── */

  /* ── CTAs don't trigger frame click ── */
  ['hvid-cta-1','hvid-cta-2'].forEach(function(id){
    var el = document.getElementById(id);
    if (el) el.addEventListener('click', function(e){ e.stopPropagation(); });
  });

  /* ── Close button + ESC stop playback completely ── */
  var closeBtn = document.getElementById('hvid-close');
  if (closeBtn) {
    closeBtn.addEventListener('click', function(e){
      e.stopPropagation();
      stopPlayback();
    });
  }
  document.addEventListener('keydown', function(e){
    if (e.key === 'Escape' && frame.classList.contains('is-playing')) {
      stopPlayback();
    }
  });
