.crow__eyebrow::after{background:linear-gradient(90deg,rgba(187,214,122,.5),transparent)}
.crow__title{font-family:"Playfair Display",serif;font-weight:700;font-size:clamp(1.8rem,3vw,2.8rem);line-height:1.1;color:#fff;letter-spacing:-.01em;margin-bottom:.9rem}
.crow__title em{font-style:italic;color:var(--heritage-gold,#D4A656)}
