.story-card.is-mono .story-card__img{display:none}.story-card.is-mono .story-card__mono{display:flex}
.story-card::before{content:"";position:absolute;inset:0;z-index:1;pointer-events:none;background:radial-gradient(120% 75% at 50% 10%,transparent 38%,rgba(5,8,16,.34) 100%),linear-gradient(180deg,rgba(255,255,255,.06) 0%,transparent 20%)}
.story-card__sheen{position:absolute;inset:0;z-index:2;pointer-events:none;background:linear-gradient(125deg,rgba(255,255,255,.12) 0%,rgba(255,255,255,.02) 16%,transparent 34%);opacity:.65;transition:opacity .6s var(--ease,cubic-bezier(.22,1,.36,1)),transform 1s var(--ease,cubic-bezier(.22,1,.36,1))}
.story-card__flag{position:absolute;top:.7rem;right:.7rem;z-index:5;display:inline-flex;align-items:center;gap:.32rem;padding:.3rem .65rem;border-radius:50px;background:rgba(5,8,16,.82);border:1px solid rgba(255,255,255,.14);font-size:.5rem;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:rgba(255,255,255,.88)}
