  var mqMobile=matchMedia('(max-width:768px)').matches, mqReduce=matchMedia('(prefers-reduced-motion:reduce)').matches;
  var coarse=matchMedia('(hover:none),(pointer:coarse)').matches, saveData=navigator.connection&&navigator.connection.saveData;
  var cores=navigator.hardwareConcurrency||0, mem=navigator.deviceMemory||0, tier;
  if(mqMobile||mqReduce||coarse||saveData) tier=1; else if((cores&&cores<=4)||(mem&&mem<=2)) tier=2; else tier=3;
  var base=COMPOSERS.map(cardHTML).join('');
  track.innerHTML=(tier===1)?base:base+base;
    requestAnimationFrame(fitChips);
    /* re-run after fonts + marquee duplication fully settle — Playwright
       and slow devices showed a stale first measurement (David Buckley
       briefly 3 rows). Multiple settle points make it deterministic. */
    setTimeout(fitChips, 120);
    setTimeout(fitChips, 600);
    if(document.fonts && document.fonts.ready){ document.fonts.ready.then(function(){ fitChips(); }); }
    addEventListener('resize', function(){ requestAnimationFrame(fitChips); }, { passive:true });
  // Reveal is owned by polish.js via [data-reveal] → .is-revealed (canonical; no dual observer here).
  if(tier===1) return;
  // seam = exact x-offset of the first duplicated card (set 2, index N).
  // Using offsetLeft of that card makes the wrap pixel-perfect (no gap-width jump).
  var N=COMPOSERS.length, single=0;
  function measure(){
    var kids=track.children;
    single = (kids.length>N) ? kids[N].offsetLeft : track.scrollWidth/2;
  }
  measure();
  addEventListener('resize',measure,{passive:true});
  var offset=0,speed=0,target=0.5,raf=null;
  function frame(){
    speed += (target-speed)*0.06;
    offset -= speed;
    if(single>0 && -offset >= single){ offset += single; } // exact wrap, invisible seam
    track.style.transform='translate3d('+offset+'px,0,0)'; // no toFixed → no sub-pixel stutter
    raf=requestAnimationFrame(frame);
  }
  function start(){if(raf==null)raf=requestAnimationFrame(frame);}
  function stop(){if(raf!=null){cancelAnimationFrame(raf);raf=null;}}
  var vo=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){measure();start();}else stop();});},{threshold:0});
  vo.observe(section);
})();
</script>
