}
.faq-item:hover{border-color:rgba(255,255,255,0.10)}
.faq-item[open]{
  border-color:rgba(117,194,73,0.16);
  background: transparent;
}

/* Summary row — matches inner-page .faq__q */
.faq-item__summary{
  list-style:none;
