}

/* Plus → × icon */
.faq-item__icon{
  flex-shrink:0;
  width:22px;height:22px;
  border-radius:50%;
  background:rgba(255,255,255,0.04);
  border:1px solid rgba(117,194,73,0.22);
  display:flex;align-items:center;justify-content:center;
  position:relative;
  transition:
    background 0.45s cubic-bezier(0.22,1,0.36,1),
    border-color 0.45s cubic-bezier(0.22,1,0.36,1),
    box-shadow 0.45s cubic-bezier(0.22,1,0.36,1),
    transform 0.55s cubic-bezier(0.22,1,0.36,1);
}
.faq-item__summary:hover .faq-item__icon{
  background:rgba(255,255,255,0.06);
  border-color:rgba(117,194,73,0.4);
}
.faq-item__icon::before,
.faq-item__icon::after{
  content:"";position:absolute;
  background:#BBD67A;
  border-radius:1px;
  transition:background 0.3s ease;
}
.faq-item__icon::before{width:9px;height:1.2px}
.faq-item__icon::after{width:1.2px;height:9px}
.faq-item[open] .faq-item__icon{
  background:rgba(117,194,73,0.32);
  border-color:#75C249;
  transform:rotate(45deg);
  box-shadow:
    0 0 16px rgba(117,194,73,0.5),
    0 0 32px rgba(187,214,122,0.15),
    inset 0 1px 0 rgba(255,255,255,0.12);
}
.faq-item[open] .faq-item__icon::before,
.faq-item[open] .faq-item__icon::after{background:#fff}

/* Smooth open/close via grid-rows. Inner uses same easing + duration both ways. */
.faq-item__body{
  display:grid;
  grid-template-rows:0fr;
  transition:grid-template-rows 0.55s cubic-bezier(0.4,0,0.2,1);
}
.faq-item[open] .faq-item__body{grid-template-rows:1fr}
.faq-item__body-inner{
  overflow:hidden;
  opacity:0;
  transition:opacity 0.4s cubic-bezier(0.4,0,0.2,1);
}
.faq-item[open] .faq-item__body-inner{opacity:1}
.faq-item__body-inner > .faq-item__a{padding:0 1.6rem 1.4rem}
@media(max-width:640px){.faq-item__body-inner > .faq-item__a{padding:0 1.1rem 1.1rem}}
.faq-item__a{
  font-family:"Outfit",sans-serif;
  font-size:0.86rem;
  font-weight:300;
  line-height:1.7;
  color:rgba(255,255,255,0.6);
  margin:0;
  padding-top:0.6rem;
  border-top:1px solid rgba(255,255,255,0.05);
}
.faq-item__a strong{font-weight:600;color:rgba(255,255,255,0.92)}
.faq-item__a a{color:#BBD67A;text-decoration:none;border-bottom:1px solid rgba(187,214,122,0.3);transition:all 0.3s ease}
.faq-item__a a:hover{color:#fff;border-bottom-color:#BBD67A}

@media(prefers-reduced-motion:reduce){
  .faq-item,.faq-item__icon,.faq-item__body{transition:none!important}
  .faq-item[open] .faq-item__icon{transform:none!important}
}
